#!/usr/bin/env python3
"""
EVLOP Single-File Standalone Distribution (`evlop_standalone.py`).
Drop this single file into ANY repository, container, or agent sandbox and run:
    python evlop_standalone.py init --bootstrap --with-hooks
    python evlop_standalone.py verify "<test-cmd>"
    python evlop_standalone.py mcp
Zero external pip dependencies required (Python 3.10+ standard library only).
"""

from __future__ import annotations

import json
from pathlib import Path
import sys
import tempfile

_EMBEDDED_MODULES: dict[str, str] = json.loads("{\n  \"__init__.py\": \"\\\"\\\"\\\"EVLOP v4.0: Universal Self-Evolving Agent Framework, HomeRail DAG Engine & Whole-System Mount SDK.\\\"\\\"\\\"\\n\\nfrom evlop.models import Episode, EvlopConfig, FailureDiagnosis, Gene, VerifyRecord\\nfrom evlop.sdk import EvlopEngine\\n\\n__version__ = \\\"0.4.0\\\"\\n\\n__all__ = [\\n    \\\"__version__\\\",\\n    \\\"EvlopEngine\\\",\\n    \\\"EvlopConfig\\\",\\n    \\\"VerifyRecord\\\",\\n    \\\"FailureDiagnosis\\\",\\n    \\\"Episode\\\",\\n    \\\"Gene\\\",\\n]\\n\",\n  \"__main__.py\": \"\\\"\\\"\\\"Allow running EVLOP directly via `python -m evlop`.\\\"\\\"\\\"\\n\\nfrom evlop.cli import entry_point\\n\\nif __name__ == \\\"__main__\\\":\\n    entry_point()\\n\",\n  \"bootstrap.py\": \"\\\"\\\"\\\"Turnkey cross-project bootstrapper so any Agent or IDE can mount EVLOP in one command.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\nimport shutil\\n\\nfrom evlop.compiler import inject_markdown_file\\nfrom evlop.models import Gene\\nfrom evlop.seed_genome import get_default_seed_genes\\nfrom evlop.store import EvlopStore\\n\\n\\n_AGENT_PROTOCOL_HEADER = \\\"\\\"\\\"# {title} \u2014 EVLOP Self-Evolving Agent Protocol\\n\\nThis project is equipped with the **EVLOP Self-Evolving Agent Engine** (`.evlop/evlop_runner.py`).\\nFollow the 5-stage loop on every coding or debugging task:\\n\\n1. **[E] Explore & Recall:** Before acting or when hitting an error, run:\\n   `python .evlop/evlop_runner.py recall \\\"<error or keyword>\\\"`\\n2. **[V] Verify Deterministically:** Run your test/build command through the gate:\\n   `python .evlop/evlop_runner.py verify \\\"<test-command>\\\"`\\n   *(If verification fails, EVLOP automatically diagnoses the stack trace and recalls matching fixes!)*\\n3. **[L] Learn & Log:** After fixing a failure and passing `verify`, log the lesson automatically:\\n   `python .evlop/evlop_runner.py log --from-last-failure --title \\\"<Rule Title>\\\" --task \\\"<Task>\\\" --root-cause \\\"<Why>\\\" --fix \\\"<How fixed>\\\"`\\n4. **[O & P] Evolve & Promote:** Compile verified high-fitness genes into project instructions:\\n   `python .evlop/evlop_runner.py evolve --target AGENTS.md,CLAUDE.md,.cursorrules`\\n\\\"\\\"\\\"\\n\\n\\ndef bootstrap_workspace(\\n    target_dir: Path,\\n    genes: list[Gene],\\n    max_genes: int = 15,\\n    with_hooks: bool = False,\\n) -> list[Path]:\\n    \\\"\\\"\\\"\\n    Vendor a zero-dependency standalone EVLOP runner into `target_dir/.evlop/`\\n    and initialize `AGENTS.md`, `CLAUDE.md`, `.cursorrules`, `.mcp.json`, and optional `.claude/settings.json`.\\n    \\\"\\\"\\\"\\n    target_dir = Path(target_dir).resolve()\\n    if not genes:\\n        genes = get_default_seed_genes()\\n        EvlopStore(target_dir).save_genes(genes)\\n    evlop_dir = target_dir / \\\".evlop\\\"\\n    vendor_pkg_dir = evlop_dir / \\\"vendor\\\" / \\\"evlop\\\"\\n    vendor_pkg_dir.mkdir(parents=True, exist_ok=True)\\n\\n    src_pkg_dir = Path(__file__).resolve().parent\\n    if src_pkg_dir.name == \\\"evlop\\\" and (src_pkg_dir / \\\"cli.py\\\").exists():\\n        for py_file in src_pkg_dir.glob(\\\"*.py\\\"):\\n            shutil.copy2(py_file, vendor_pkg_dir / py_file.name)\\n\\n    runner_path = evlop_dir / \\\"evlop_runner.py\\\"\\n    runner_code = '''#!/usr/bin/env python3\\n\\\"\\\"\\\"Standalone zero-install EVLOP runner for external agent workspaces.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\nimport sys\\n\\n_HERE = Path(__file__).resolve().parent\\nsys.path.insert(0, str(_HERE / \\\"vendor\\\"))\\n\\nfrom evlop.cli import entry_point  # noqa: E402\\n\\nif __name__ == \\\"__main__\\\":\\n    entry_point()\\n'''\\n    runner_path.write_text(runner_code, encoding=\\\"utf-8\\\")\\n\\n    created: list[Path] = [runner_path]\\n    for doc_name in [\\\"AGENTS.md\\\", \\\"CLAUDE.md\\\", \\\".cursorrules\\\"]:\\n        doc_path = target_dir / doc_name\\n        if not doc_path.exists():\\n            doc_path.write_text(\\n                _AGENT_PROTOCOL_HEADER.format(title=doc_name),\\n                encoding=\\\"utf-8\\\",\\n            )\\n        inject_markdown_file(doc_path, genes, max_genes=max_genes)\\n        created.append(doc_path)\\n\\n    mcp_json_path = target_dir / \\\".mcp.json\\\"\\n    mcp_payload = {\\n        \\\"mcpServers\\\": {\\n            \\\"evlop\\\": {\\n                \\\"command\\\": \\\"python\\\",\\n                \\\"args\\\": [\\\".evlop/evlop_runner.py\\\", \\\"mcp\\\"],\\n            }\\n        }\\n    }\\n    mcp_json_path.write_text(\\n        json.dumps(mcp_payload, indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    created.append(mcp_json_path)\\n\\n    if with_hooks:\\n        claude_dir = target_dir / \\\".claude\\\"\\n        claude_dir.mkdir(parents=True, exist_ok=True)\\n        settings_path = claude_dir / \\\"settings.json\\\"\\n        hooks_payload = {\\n            \\\"hooks\\\": {\\n                \\\"SessionStart\\\": [\\n                    {\\n                        \\\"hooks\\\": [\\n                            {\\n                                \\\"type\\\": \\\"command\\\",\\n                                \\\"command\\\": \\\"python .evlop/evlop_runner.py status\\\",\\n                            }\\n                        ]\\n                    }\\n                ],\\n                \\\"Stop\\\": [\\n                    {\\n                        \\\"hooks\\\": [\\n                            {\\n                                \\\"type\\\": \\\"command\\\",\\n                                \\\"command\\\": \\\"python .evlop/evlop_runner.py evolve --target AGENTS.md,CLAUDE.md,.cursorrules\\\",\\n                            }\\n                        ]\\n                    }\\n                ],\\n            }\\n        }\\n        settings_path.write_text(\\n            json.dumps(hooks_payload, indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n            encoding=\\\"utf-8\\\",\\n        )\\n        created.append(settings_path)\\n\\n    return created\\n\",\n  \"cli.py\": \"\\\"\\\"\\\"CLI entrypoint for EVLOP v3.0: init, recall, verify, log, mutate, lineage, evolve, export-skill, dag, scorecard, replay, status, mcp.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport sys\\n\\nfrom evlop.bootstrap import bootstrap_workspace\\nfrom evlop.compiler import export_gene_to_skill, inject_markdown_file, render_lineage_mermaid\\nfrom evlop.dag_rail import DagCycleError, execute_dag_rail\\nfrom evlop.fitness import govern_genes\\nfrom evlop.models import Episode, Gene, slugify_gene_id, utc_now_iso\\nfrom evlop.quality_gate import audit_python_path\\nfrom evlop.store import EvlopStore\\nfrom evlop.verifier import extract_failure_diagnosis, run_verification\\n\\n\\ndef _safe_print(text: str, file=None) -> None:\\n    \\\"\\\"\\\"Print text safely even if the target console stream uses strict legacy encoding (e.g. Windows gbk).\\\"\\\"\\\"\\n    stream = file if file is not None else sys.stdout\\n    try:\\n        print(text, file=stream)\\n    except UnicodeEncodeError:\\n        enc = getattr(stream, \\\"encoding\\\", None) or \\\"utf-8\\\"\\n        safe_text = text.encode(enc, errors=\\\"replace\\\").decode(enc, errors=\\\"replace\\\")\\n        print(safe_text, file=stream)\\n\\n\\ndef _build_parser() -> argparse.ArgumentParser:\\n    parser = argparse.ArgumentParser(\\n        prog=\\\"evlop\\\",\\n        description=\\\"EVLOP v3.0: Heterogeneous Multi-Agent DAG Rail & Darwinian Self-Evolution Engine\\\",\\n    )\\n    sub = parser.add_subparsers(dest=\\\"subcommand\\\", required=True)\\n\\n    p_init = sub.add_parser(\\\"init\\\", help=\\\"Initialize .evlop/ workspace store and optional full agent bootstrap\\\")\\n    p_init.add_argument(\\\"--target-dir\\\", default=\\\".\\\", help=\\\"Workspace directory\\\")\\n    p_init.add_argument(\\n        \\\"--bootstrap\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Vendor standalone .evlop/evlop_runner.py and create AGENTS.md, CLAUDE.md, and .cursorrules\\\",\\n    )\\n    p_init.add_argument(\\n        \\\"--with-hooks\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Also generate .claude/settings.json automatic SessionStart and Stop evolution hooks\\\",\\n    )\\n\\n    p_recall = sub.add_parser(\\\"recall\\\", help=\\\"[Stage E] Recall relevant evolved genes before acting\\\")\\n    p_recall.add_argument(\\\"query\\\", help=\\\"Search keywords, error message, or '*' for top genes\\\")\\n    p_recall.add_argument(\\\"--top\\\", type=int, default=5, help=\\\"Max genes to return\\\")\\n\\n    p_verify = sub.add_parser(\\\"verify\\\", help=\\\"[Stage V] Run deterministic verification command gate\\\")\\n    p_verify.add_argument(\\\"command\\\", help=\\\"Shell command to execute (e.g. pytest, npm test)\\\")\\n    p_verify.add_argument(\\\"--timeout\\\", type=int, default=120, help=\\\"Timeout in seconds\\\")\\n    p_verify.add_argument(\\n        \\\"--quality-gate\\\",\\n        default=\\\"\\\",\\n        help=\\\"Optional Python file or directory path to enforce AST code quality & complexity gate (>= min-quality-score)\\\",\\n    )\\n    p_verify.add_argument(\\n        \\\"--min-quality-score\\\",\\n        type=float,\\n        default=90.0,\\n        help=\\\"Minimum AST quality score required when --quality-gate is enabled (default 90.0)\\\",\\n    )\\n\\n    p_audit = sub.add_parser(\\n        \\\"audit\\\",\\n        help=\\\"[Stage V+] Run deterministic AST code quality & O(N^2) complexity auditor on Python files\\\",\\n    )\\n    p_audit.add_argument(\\\"path\\\", default=\\\".\\\", nargs=\\\"?\\\", help=\\\"Python file or directory to audit\\\")\\n    p_audit.add_argument(\\\"--min-score\\\", type=float, default=90.0, help=\\\"Minimum passing score (0..100)\\\")\\n    p_audit.add_argument(\\\"--json\\\", action=\\\"store_true\\\", help=\\\"Output audit report as JSON\\\")\\n\\n    p_log = sub.add_parser(\\\"log\\\", help=\\\"[Stage L] Record an episode and create/reinforce a gene\\\")\\n    p_log.add_argument(\\\"--title\\\", default=\\\"\\\", help=\\\"Short imperative rule title\\\")\\n    p_log.add_argument(\\\"--task\\\", required=True, help=\\\"Summary of the task being solved\\\")\\n    p_log.add_argument(\\\"--symptom\\\", default=\\\"\\\", help=\\\"Failure symptom or problem encountered\\\")\\n    p_log.add_argument(\\n        \\\"--from-last-failure\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Auto-populate symptom and trigger from .evlop/last_failure.json\\\",\\n    )\\n    p_log.add_argument(\\\"--root-cause\\\", required=True, help=\\\"Diagnosed root cause\\\")\\n    p_log.add_argument(\\\"--fix\\\", required=True, help=\\\"Fix applied\\\")\\n    p_log.add_argument(\\n        \\\"--category\\\",\\n        default=\\\"debugging\\\",\\n        choices=[\\\"debugging\\\", \\\"architecture\\\", \\\"testing\\\", \\\"tooling\\\", \\\"workflow\\\"],\\n        help=\\\"Gene category\\\",\\n    )\\n    p_log.add_argument(\\\"--trigger\\\", default=\\\"\\\", help=\\\"Trigger condition for activating the gene\\\")\\n    p_log.add_argument(\\\"--strategy\\\", default=\\\"\\\", help=\\\"Reusable actionable strategy\\\")\\n    p_log.add_argument(\\\"--anti-pattern\\\", default=\\\"Blindly guessing without verification\\\", help=\\\"What to avoid\\\")\\n    p_log.add_argument(\\\"--agent-id\\\", default=\\\"\\\", help=\\\"Swarm agent identifier (or EVLOP_AGENT_ID env)\\\")\\n    p_log.add_argument(\\\"--failed\\\", action=\\\"store_true\\\", help=\\\"Mark that applying this strategy failed\\\")\\n\\n    p_mutate = sub.add_parser(\\n        \\\"mutate\\\",\\n        help=\\\"[Stage O - DGM Mode] Evolve a child gene mutation from an existing parent gene\\\",\\n    )\\n    p_mutate.add_argument(\\\"--parent-id\\\", required=True, help=\\\"Parent gene ID to mutate from\\\")\\n    p_mutate.add_argument(\\\"--title\\\", required=True, help=\\\"New mutated gene title\\\")\\n    p_mutate.add_argument(\\\"--strategy\\\", required=True, help=\\\"Mutated strategy\\\")\\n    p_mutate.add_argument(\\\"--reason\\\", default=\\\"Empirical refinement\\\", help=\\\"Reason for mutation\\\")\\n    p_mutate.add_argument(\\\"--trigger\\\", default=\\\"\\\", help=\\\"Optional updated trigger (defaults to parent trigger)\\\")\\n    p_mutate.add_argument(\\\"--agent-id\\\", default=\\\"\\\", help=\\\"Swarm agent identifier\\\")\\n\\n    p_lineage = sub.add_parser(\\n        \\\"lineage\\\",\\n        help=\\\"[Stage O - DGM Archive] Inspect or export the phylogenetic evolution tree of genes\\\",\\n    )\\n    p_lineage.add_argument(\\\"--mermaid\\\", action=\\\"store_true\\\", help=\\\"Render as Mermaid flowchart\\\")\\n    p_lineage.add_argument(\\\"--out\\\", default=\\\"\\\", help=\\\"Optional file path to write lineage output\\\")\\n\\n    p_evolve = sub.add_parser(\\n        \\\"evolve\\\",\\n        help=\\\"[Stages O & P] Govern genome (merge/score/prune) and compile top genes into AGENTS.md/CLAUDE.md\\\",\\n    )\\n    p_evolve.add_argument(\\n        \\\"--target\\\",\\n        default=\\\"AGENTS.md,CLAUDE.md\\\",\\n        help=\\\"Comma-separated markdown files to update with promoted genes\\\",\\n    )\\n\\n    p_skill = sub.add_parser(\\n        \\\"export-skill\\\",\\n        help=\\\"[Stage P - Voyager Mode] Export a verified gene into a standalone SKILL.md directory\\\",\\n    )\\n    p_skill.add_argument(\\\"--gene-id\\\", required=True, help=\\\"ID of the gene to export\\\")\\n    p_skill.add_argument(\\\"--out-dir\\\", default=\\\"skills\\\", help=\\\"Output skills directory\\\")\\n    p_skill.add_argument(\\n        \\\"--synthesize-script\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Also synthesize an executable Python tool script under scripts/run_strategy.py\\\",\\n    )\\n\\n    # HomeRail Heterogeneous Multi-Agent DAG Rail Commands\\n    p_dag = sub.add_parser(\\n        \\\"dag\\\",\\n        help=\\\"[HomeRail Mode] Run or supervise a heterogeneous multi-agent DAG workflow in parallel waves\\\",\\n    )\\n    p_dag.add_argument(\\\"action\\\", choices=[\\\"run\\\", \\\"supervise\\\"], help=\\\"DAG action\\\")\\n    p_dag.add_argument(\\\"spec\\\", help=\\\"Path to DAG specification JSON file\\\")\\n    p_dag.add_argument(\\\"--run-id\\\", default=\\\"\\\", help=\\\"Optional explicit run identifier\\\")\\n\\n    p_scorecard = sub.add_parser(\\n        \\\"scorecard\\\",\\n        help=\\\"[HomeRail Mode] Inspect evaluation scorecard for a completed DAG run\\\",\\n    )\\n    p_scorecard.add_argument(\\\"run_id\\\", help=\\\"DAG run ID\\\")\\n    p_scorecard.add_argument(\\\"--json\\\", action=\\\"store_true\\\", help=\\\"Output scorecard as JSON\\\")\\n\\n    p_replay = sub.add_parser(\\n        \\\"replay\\\",\\n        help=\\\"[HomeRail Mode] Replay or audit a previous DAG run (optionally starting from a specific node)\\\",\\n    )\\n    p_replay.add_argument(\\\"run_id\\\", help=\\\"DAG run ID to replay\\\")\\n    p_replay.add_argument(\\\"--from-node\\\", default=\\\"\\\", help=\\\"Node ID to resume execution from\\\")\\n\\n    p_status = sub.add_parser(\\\"status\\\", help=\\\"Inspect EVLOP genome health, swarm contributors, and lineage depth\\\")\\n    p_status.add_argument(\\\"--json\\\", action=\\\"store_true\\\", help=\\\"Output status as JSON\\\")\\n\\n    sub.add_parser(\\\"mcp\\\", help=\\\"Run zero-dependency MCP JSON-RPC 2.0 server over stdio\\\")\\n\\n    return parser\\n\\n\\ndef main(argv: list[str] | None = None, root_dir: Path | None = None) -> int:\\n    parser = _build_parser()\\n    args = parser.parse_args(argv)\\n    workspace = Path(root_dir).resolve() if root_dir else Path.cwd().resolve()\\n\\n    if args.subcommand == \\\"init\\\":\\n        target = (workspace / args.target_dir).resolve() if not root_dir else workspace\\n        store = EvlopStore(target)\\n        evlop_path = store.init_store()\\n        cfg = store.load_config()\\n        if args.bootstrap or args.with_hooks:\\n            created = bootstrap_workspace(\\n                target,\\n                store.load_genes(),\\n                max_genes=cfg.max_active_genes,\\n                with_hooks=args.with_hooks,\\n            )\\n            _safe_print(\\n                f\\\"[EVLOP Bootstrap] Initialized {evlop_path} and bootstrapped {len(created)} agent protocol files.\\\"\\n            )\\n        else:\\n            _safe_print(f\\\"[EVLOP] Initialized self-evolution store at {evlop_path}\\\")\\n        return 0\\n\\n    store = EvlopStore(workspace)\\n    store.init_store()\\n    cfg = store.load_config()\\n\\n    if args.subcommand == \\\"mcp\\\":\\n        from evlop.mcp_server import run_stdio_server\\n\\n        return run_stdio_server(workspace)\\n\\n    if args.subcommand == \\\"dag\\\":\\n        spec_path = Path(args.spec)\\n        if not spec_path.is_absolute():\\n            spec_path = (workspace / spec_path).resolve()\\n        try:\\n            record = execute_dag_rail(spec_path, workspace=workspace, store=store, run_id=args.run_id)\\n        except (DagCycleError, FileNotFoundError, json.JSONDecodeError, KeyError) as exc:\\n            _safe_print(f\\\"[EVLOP DAG Error] {exc}\\\", file=sys.stderr)\\n            return 1\\n\\n        sc = record.scorecard\\n        _safe_print(\\n            f\\\"[EVLOP DAG {record.status.upper()}] Run: {record.run_id} | Rail: {record.rail_id} | \\\"\\n            f\\\"Waves: {len(record.waves)} | Score: {sc['overall_score']}% | \\\"\\n            f\\\"Speedup: {sc['parallel_speedup_factor']}x | Agents: {', '.join(sc['heterogeneous_agents'])}\\\"\\n        )\\n        return 0 if record.status == \\\"passed\\\" else 1\\n\\n    if args.subcommand == \\\"scorecard\\\":\\n        run_file = store.evlop_dir / \\\"runs\\\" / f\\\"{args.run_id}.json\\\"\\n        if not run_file.exists():\\n            _safe_print(f\\\"[EVLOP Error] Run '{args.run_id}' not found.\\\", file=sys.stderr)\\n            return 1\\n        data = json.loads(run_file.read_text(encoding=\\\"utf-8\\\"))\\n        sc = data.get(\\\"scorecard\\\", {})\\n        if args.json:\\n            _safe_print(json.dumps(sc, indent=2, ensure_ascii=False))\\n        else:\\n            _safe_print(\\n                f\\\"[EVLOP Scorecard] Run: {args.run_id} ({data.get('rail_id')})\\\\n\\\"\\n                f\\\"  Overall Score : {sc.get('overall_score')}% ({sc.get('passed_nodes')}/{sc.get('total_nodes')} nodes passed)\\\\n\\\"\\n                f\\\"  Speedup Factor: {sc.get('parallel_speedup_factor')}x (Wall: {sc.get('wall_clock_ms')}ms)\\\\n\\\"\\n                f\\\"  Agent Mix     : {', '.join(sc.get('heterogeneous_agents', []))}\\\\n\\\"\\n                f\\\"  Genes Recalled: {sc.get('total_genes_recalled', 0)}\\\"\\n            )\\n        return 0\\n\\n    if args.subcommand == \\\"replay\\\":\\n        run_file = store.evlop_dir / \\\"runs\\\" / f\\\"{args.run_id}.json\\\"\\n        if not run_file.exists():\\n            _safe_print(f\\\"[EVLOP Error] Run '{args.run_id}' not found.\\\", file=sys.stderr)\\n            return 1\\n        prior_data = json.loads(run_file.read_text(encoding=\\\"utf-8\\\"))\\n        spec_path = Path(prior_data[\\\"spec_path\\\"])\\n        record = execute_dag_rail(\\n            spec_path,\\n            workspace=workspace,\\n            store=store,\\n            run_id=f\\\"{args.run_id}-replay\\\",\\n            start_from_node=args.from_node,\\n            prior_results=prior_data.get(\\\"node_results\\\", {}),\\n        )\\n        _safe_print(\\n            f\\\"[EVLOP Replay {record.status.upper()}] Replayed '{args.run_id}' -> '{record.run_id}' \\\"\\n            f\\\"(Score: {record.scorecard['overall_score']}%)\\\"\\n        )\\n        return 0 if record.status == \\\"passed\\\" else 1\\n\\n    if args.subcommand == \\\"recall\\\":\\n        matches = store.recall_genes(args.query, top_k=args.top)\\n        if not matches:\\n            _safe_print(f\\\"[EVLOP Recall] No matching genes found for '{args.query}'.\\\")\\n            return 0\\n        _safe_print(f\\\"[EVLOP Recall] Top {len(matches)} matching gene(s):\\\")\\n        for g in matches:\\n            _safe_print(\\n                f\\\"  - [{g.status.upper()}] {g.id} (gen={g.generation}, fitness={g.fitness:.2f}): {g.title}\\\\n\\\"\\n                f\\\"    Trigger : {g.trigger}\\\\n\\\"\\n                f\\\"    Strategy: {g.strategy}\\\"\\n            )\\n        return 0\\n\\n    if args.subcommand == \\\"audit\\\":\\n        target_p = Path(args.path)\\n        if not target_p.is_absolute():\\n            target_p = (workspace / target_p).resolve()\\n        q_report = audit_python_path(target_p, min_score=args.min_score)\\n        if args.json:\\n            _safe_print(json.dumps(q_report.to_dict(), indent=2, ensure_ascii=False))\\n        else:\\n            status_tag = \\\"PASSED\\\" if q_report.passed else \\\"FAILED\\\"\\n            _safe_print(\\n                f\\\"[EVLOP AST Audit {status_tag}] Score: {q_report.score}/100.0 \\\"\\n                f\\\"(Min: {q_report.min_score} | Scanned: {q_report.files_scanned} file(s) | Findings: {len(q_report.findings)})\\\"\\n            )\\n            for f in q_report.findings:\\n                _safe_print(f\\\"  - [{f.severity.upper()}] {f.file}:{f.line} ({f.rule_id}, -{f.penalty}): {f.message}\\\")\\n        return 0 if q_report.passed else 1\\n\\n    if args.subcommand == \\\"verify\\\":\\n        record = run_verification(args.command, cwd=workspace, timeout_sec=args.timeout)\\n        if record.passed and args.quality_gate:\\n            qg_path = Path(args.quality_gate)\\n            if not qg_path.is_absolute():\\n                qg_path = (workspace / qg_path).resolve()\\n            q_rep = audit_python_path(qg_path, min_score=args.min_quality_score)\\n            if not q_rep.passed:\\n                record.passed = False\\n                record.exit_code = 2\\n                findings_txt = \\\"; \\\".join(f\\\"{f.file}:{f.line} {f.rule_id}\\\" for f in q_rep.findings)\\n                record.output_snippet = (\\n                    f\\\"{record.output_snippet}\\\\n[EVLOP Quality Gate FAILED] AST Score {q_rep.score} < {q_rep.min_score}: {findings_txt}\\\"\\n                ).strip()\\n        with store.lock():\\n            store.save_verify(record)\\n            status_str = \\\"PASSED\\\" if record.passed else f\\\"FAILED (exit={record.exit_code})\\\"\\n            _safe_print(f\\\"[EVLOP Verify] {status_str} ({record.duration_ms:.1f}ms) -> {record.command}\\\")\\n            if record.output_snippet:\\n                _safe_print(record.output_snippet)\\n            if not record.passed:\\n                diag = extract_failure_diagnosis(record)\\n                store.save_failure(diag)\\n                hints = store.recall_genes(f\\\"{diag.error_type} {diag.symptom_summary}\\\", top_k=3)\\n                if hints:\\n                    _safe_print(f\\\"\\\\n[EVLOP Auto-Recall Hint] Found {len(hints)} matching gene(s) for {diag.error_type}:\\\")\\n                    for h in hints:\\n                        _safe_print(f\\\"  * {h.title} ({h.id}): {h.strategy}\\\")\\n        return 0 if record.passed else (record.exit_code or 1)\\n\\n    if args.subcommand == \\\"log\\\":\\n        with store.lock():\\n            last_v = store.load_last_verify()\\n            is_verified = bool(\\n                store.is_verify_fresh(last_v, ttl_minutes=cfg.verify_ttl_minutes)\\n                and not args.failed\\n            )\\n            verify_cmd = last_v.command if last_v else \\\"\\\"\\n            agent_id = args.agent_id.strip() or os.environ.get(\\\"EVLOP_AGENT_ID\\\", \\\"default-agent\\\")\\n\\n            symptom = args.symptom.strip()\\n            trigger = args.trigger.strip()\\n            if args.from_last_failure:\\n                last_fail = store.load_last_failure()\\n                if last_fail:\\n                    if not symptom:\\n                        symptom = f\\\"{last_fail.error_type}: {last_fail.symptom_summary}\\\"\\n                    if not trigger:\\n                        trigger = f\\\"{last_fail.error_type} {last_fail.symptom_summary}\\\"\\n            if not symptom:\\n                symptom = args.task.strip()\\n\\n            title = args.title.strip() or args.fix.strip()[:60]\\n            gene_id = slugify_gene_id(title)\\n            now_iso = utc_now_iso()\\n            ep_hash = hashlib.sha1(f\\\"{now_iso}:{args.task}:{gene_id}:{agent_id}\\\".encode(\\\"utf-8\\\")).hexdigest()[:10]\\n\\n            episode = Episode(\\n                episode_id=f\\\"ep-{ep_hash}\\\",\\n                timestamp=now_iso,\\n                task_summary=args.task,\\n                failure_symptom=symptom,\\n                root_cause=args.root_cause,\\n                fix_applied=args.fix,\\n                verified=is_verified,\\n                verify_cmd=verify_cmd,\\n                gene_id=gene_id,\\n                agent_id=agent_id,\\n            )\\n            store.append_episode(episode)\\n\\n            genes = store.load_genes()\\n            new_gene = Gene(\\n                id=gene_id,\\n                title=title,\\n                category=args.category,\\n                trigger=trigger or symptom,\\n                strategy=args.strategy.strip() or args.fix.strip(),\\n                anti_pattern=args.anti_pattern.strip(),\\n                success_count=1 if is_verified else 0,\\n                failure_count=1 if args.failed else 0,\\n                verified_gate=is_verified,\\n                created_at=now_iso,\\n                last_used_at=now_iso,\\n                contributors=[agent_id],\\n                best_duration_ms=last_v.duration_ms if (is_verified and last_v) else 0.0,\\n            )\\n            genes.append(new_gene)\\n            governed = govern_genes(genes, cfg)\\n            store.save_genes(governed)\\n        _safe_print(\\n            f\\\"[EVLOP Log] Recorded episode {episode.episode_id} (agent={agent_id}) -> gene {gene_id} (verified={is_verified})\\\"\\n        )\\n        return 0\\n\\n    if args.subcommand == \\\"mutate\\\":\\n        with store.lock():\\n            genes = store.load_genes()\\n            by_id = {g.id: g for g in genes}\\n            if args.parent_id not in by_id:\\n                _safe_print(f\\\"[EVLOP Error] Parent gene '{args.parent_id}' not found.\\\", file=sys.stderr)\\n                return 1\\n            parent = by_id[args.parent_id]\\n            last_v = store.load_last_verify()\\n            is_verified = store.is_verify_fresh(last_v, ttl_minutes=cfg.verify_ttl_minutes)\\n            agent_id = args.agent_id.strip() or os.environ.get(\\\"EVLOP_AGENT_ID\\\", \\\"default-agent\\\")\\n            now_iso = utc_now_iso()\\n            child_id = slugify_gene_id(args.title.strip())\\n            if child_id == parent.id:\\n                suffix = hashlib.sha1(f\\\"{args.title}:{args.strategy}\\\".encode(\\\"utf-8\\\")).hexdigest()[:6]\\n                child_id = f\\\"{child_id}-gen{parent.generation + 1}-{suffix}\\\"\\n\\n            child_gene = Gene(\\n                id=child_id,\\n                title=args.title.strip(),\\n                category=parent.category,\\n                trigger=args.trigger.strip() or parent.trigger,\\n                strategy=args.strategy.strip(),\\n                anti_pattern=parent.anti_pattern,\\n                success_count=1 if is_verified else 0,\\n                failure_count=0,\\n                verified_gate=is_verified,\\n                created_at=now_iso,\\n                last_used_at=now_iso,\\n                parent_id=parent.id,\\n                generation=parent.generation + 1,\\n                mutation_reason=args.reason.strip(),\\n                contributors=sorted(set(parent.contributors) | {agent_id}),\\n                best_duration_ms=last_v.duration_ms if (is_verified and last_v) else 0.0,\\n            )\\n            genes.append(child_gene)\\n            governed = govern_genes(genes, cfg)\\n            store.save_genes(governed)\\n        _safe_print(\\n            f\\\"[EVLOP Mutate] Evolved Gen-{child_gene.generation} gene '{child_gene.id}' from '{parent.id}'\\\"\\n        )\\n        return 0\\n\\n    if args.subcommand == \\\"lineage\\\":\\n        genes = govern_genes(store.load_genes(), cfg)\\n        output = render_lineage_mermaid(genes)\\n        if args.out:\\n            out_path = workspace / args.out\\n            out_path.write_text(output, encoding=\\\"utf-8\\\")\\n            _safe_print(f\\\"[EVLOP Lineage] Wrote phylogenetic tree to {out_path}\\\")\\n        else:\\n            _safe_print(output)\\n        return 0\\n\\n    if args.subcommand == \\\"evolve\\\":\\n        with store.lock():\\n            genes = store.load_genes()\\n            governed = govern_genes(genes, cfg)\\n            store.save_genes(governed)\\n\\n            targets = [t.strip() for t in args.target.split(\\\",\\\") if t.strip()]\\n            for rel_target in targets:\\n                target_path = workspace / rel_target\\n                inject_markdown_file(target_path, governed, max_genes=cfg.max_active_genes)\\n\\n        promoted_cnt = sum(1 for g in governed if g.status == \\\"promoted\\\")\\n        archived_cnt = sum(1 for g in governed if g.status == \\\"archived\\\")\\n        _safe_print(\\n            f\\\"[EVLOP Evolve] Governed {len(governed)} genes \\\"\\n            f\\\"(promoted={promoted_cnt}, archived={archived_cnt}) -> updated {', '.join(targets)}\\\"\\n        )\\n        return 0\\n\\n    if args.subcommand == \\\"export-skill\\\":\\n        genes = {g.id: g for g in store.load_genes()}\\n        if args.gene_id not in genes:\\n            _safe_print(f\\\"[EVLOP Error] Gene '{args.gene_id}' not found.\\\", file=sys.stderr)\\n            return 1\\n        target_gene = genes[args.gene_id]\\n        if not target_gene.verified_gate or target_gene.status == \\\"archived\\\":\\n            _safe_print(\\n                f\\\"[EVLOP Error] Refusing to export unverified or archived gene '{args.gene_id}'.\\\",\\n                file=sys.stderr,\\n            )\\n            return 1\\n        out_root = workspace / args.out_dir\\n        skill_path = export_gene_to_skill(\\n            target_gene,\\n            out_root,\\n            synthesize_script=args.synthesize_script,\\n        )\\n        _safe_print(f\\\"[EVLOP Export-Skill] Created {skill_path}\\\")\\n        return 0\\n\\n    if args.subcommand == \\\"status\\\":\\n        genes = govern_genes(store.load_genes(), cfg)\\n        episodes = store.load_episodes()\\n        last_v = store.load_last_verify()\\n        all_agents = sorted({c for g in genes for c in g.contributors})\\n        max_gen = max((g.generation for g in genes), default=0)\\n        summary = {\\n            \\\"total_episodes\\\": len(episodes),\\n            \\\"total_genes\\\": len(genes),\\n            \\\"promoted_genes\\\": sum(1 for g in genes if g.status == \\\"promoted\\\"),\\n            \\\"candidate_genes\\\": sum(1 for g in genes if g.status == \\\"candidate\\\"),\\n            \\\"archived_genes\\\": sum(1 for g in genes if g.status == \\\"archived\\\"),\\n            \\\"max_generation\\\": max_gen,\\n            \\\"swarm_contributors\\\": all_agents,\\n            \\\"last_verify\\\": last_v.to_dict() if last_v else None,\\n            \\\"top_genes\\\": [g.to_dict() for g in genes[:5]],\\n        }\\n        if args.json:\\n            _safe_print(json.dumps(summary, indent=2, ensure_ascii=False))\\n        else:\\n            _safe_print(\\n                f\\\"[EVLOP Status] Episodes: {summary['total_episodes']} | \\\"\\n                f\\\"Genes: {summary['total_genes']} \\\"\\n                f\\\"(Promoted: {summary['promoted_genes']}, \\\"\\n                f\\\"Candidate: {summary['candidate_genes']}, \\\"\\n                f\\\"Archived: {summary['archived_genes']}, \\\"\\n                f\\\"MaxGen: {summary['max_generation']})\\\"\\n            )\\n        return 0\\n\\n    return 1\\n\\n\\ndef entry_point() -> None:\\n    sys.exit(main())\\n\",\n  \"compiler.py\": \"\\\"\\\"\\\"Markdown marker injection, DGM phylogenetic lineage rendering, and Voyager skill/tool synthesis.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\nimport re\\n\\nfrom evlop.models import Gene\\n\\nMARKER_START = \\\"<!-- EVLOP:START -->\\\"\\nMARKER_END = \\\"<!-- EVLOP:END -->\\\"\\n_START_LINE_RE = re.compile(r\\\"^[ \\\\t]*<!-- EVLOP:START -->[ \\\\t]*$\\\", re.MULTILINE)\\n_END_LINE_RE = re.compile(r\\\"^[ \\\\t]*<!-- EVLOP:END -->[ \\\\t]*$\\\", re.MULTILINE)\\n_BACKTICK_CMD_RE = re.compile(r\\\"`([^`]+)`\\\")\\n\\n\\ndef render_genes_markdown(genes: list[Gene], max_genes: int = 15) -> str:\\n    \\\"\\\"\\\"Render top promoted genes into a bounded, structured Markdown block.\\\"\\\"\\\"\\n    promoted = [g for g in genes if g.status == \\\"promoted\\\"]\\n    promoted.sort(key=lambda g: (g.fitness, g.success_count), reverse=True)\\n    selected = promoted[:max_genes]\\n\\n    lines = [\\n        MARKER_START,\\n        \\\"## EVLOP Evolved Genome (Auto-Compiled High-Fitness Rules)\\\",\\n        \\\"\\\",\\n        \\\"> Managed automatically by `evlop evolve`. Only verified rules (`verified_gate=True`) with high Darwinian fitness are promoted here (capped at top \\\"\\n        f\\\"{max_genes} genes to prevent Context Rot).\\\",\\n        \\\"\\\",\\n    ]\\n\\n    if not selected:\\n        lines.append(\\\"_No promoted genes yet. Run `evlop verify` -> `evlop log` -> `evlop evolve` to evolve rules._\\\")\\n    else:\\n        for idx, g in enumerate(selected, start=1):\\n            lineage_tag = f\\\" | Gen `{g.generation}`\\\" + (f\\\" from `{g.parent_id}`\\\" if g.parent_id else \\\"\\\")\\n            lines.extend(\\n                [\\n                    f\\\"### {idx}. [{g.category.upper()}] {g.title} (`{g.id}` | Fitness: `{g.fitness:.2f}` | S/F: `{g.success_count}/{g.failure_count}`{lineage_tag})\\\",\\n                    f\\\"- **Trigger (When):** {g.trigger}\\\",\\n                    f\\\"- **Strategy (Do):** {g.strategy}\\\",\\n                    f\\\"- **Anti-Pattern (Avoid):** {g.anti_pattern}\\\",\\n                    \\\"\\\",\\n                ]\\n            )\\n\\n    lines.append(MARKER_END)\\n    return \\\"\\\\n\\\".join(lines)\\n\\n\\ndef inject_markdown_file(file_path: Path, genes: list[Gene], max_genes: int = 15) -> None:\\n    \\\"\\\"\\\"Inject or update the EVLOP genome block inside a Markdown file matching standalone marker lines only.\\\"\\\"\\\"\\n    block = render_genes_markdown(genes, max_genes=max_genes)\\n    if not file_path.exists():\\n        header = f\\\"# {file_path.stem} \u2014 Agent Instructions\\\\n\\\\n\\\"\\n        file_path.write_text(header + block + \\\"\\\\n\\\", encoding=\\\"utf-8\\\")\\n        return\\n\\n    existing = file_path.read_text(encoding=\\\"utf-8\\\")\\n    m_start = _START_LINE_RE.search(existing)\\n    m_end = _END_LINE_RE.search(existing)\\n\\n    if m_start and m_end and m_start.start() < m_end.start():\\n        updated = existing[: m_start.start()] + block + existing[m_end.end() :]\\n    else:\\n        cleaned = _START_LINE_RE.sub(\\\"\\\", existing)\\n        cleaned = _END_LINE_RE.sub(\\\"\\\", cleaned).rstrip()\\n        updated = f\\\"{cleaned}\\\\n\\\\n{block}\\\\n\\\" if cleaned else f\\\"{block}\\\\n\\\"\\n\\n    file_path.write_text(updated, encoding=\\\"utf-8\\\")\\n\\n\\ndef render_lineage_mermaid(genes: list[Gene]) -> str:\\n    \\\"\\\"\\\"Render a Darwin G\u00f6del Machine (DGM) style phylogenetic evolution tree in Mermaid format.\\\"\\\"\\\"\\n    lines = [\\n        \\\"# EVLOP Phylogenetic Lineage Tree (DGM Evolution Archive)\\\",\\n        \\\"\\\",\\n        \\\"```mermaid\\\",\\n        \\\"flowchart TD\\\",\\n    ]\\n    if not genes:\\n        lines.append('    empty[\\\"No genes in archive yet\\\"]')\\n    else:\\n        for g in genes:\\n            clean_title = g.title.replace('\\\"', \\\"'\\\")\\n            label = f\\\"{g.id}<br/>Gen {g.generation}: {clean_title}<br/>Fitness: {g.fitness:.2f} ({g.status})\\\"\\n            lines.append(f'    {g.id}[\\\"{label}\\\"]')\\n        for g in genes:\\n            if g.parent_id:\\n                reason = g.mutation_reason.replace('\\\"', \\\"'\\\")[:36] if g.mutation_reason else \\\"mutated\\\"\\n                lines.append(f'    {g.parent_id} -->|\\\"{reason}\\\"| {g.id}')\\n    lines.append(\\\"```\\\")\\n    return \\\"\\\\n\\\".join(lines) + \\\"\\\\n\\\"\\n\\n\\ndef _synthesize_voyager_script(gene: Gene, scripts_dir: Path) -> Path:\\n    \\\"\\\"\\\"Synthesize a Voyager-style executable Python helper tool from a Gene's strategy.\\\"\\\"\\\"\\n    scripts_dir.mkdir(parents=True, exist_ok=True)\\n    script_path = scripts_dir / \\\"run_strategy.py\\\"\\n\\n    cmd_match = _BACKTICK_CMD_RE.search(gene.strategy)\\n    extracted_cmd = cmd_match.group(1) if cmd_match else \\\"\\\"\\n\\n    meta = {\\n        \\\"gene_id\\\": gene.id,\\n        \\\"title\\\": gene.title,\\n        \\\"category\\\": gene.category,\\n        \\\"generation\\\": gene.generation,\\n        \\\"parent_id\\\": gene.parent_id,\\n        \\\"strategy\\\": gene.strategy,\\n        \\\"extracted_command\\\": extracted_cmd,\\n    }\\n    meta_json = json.dumps(meta, indent=2, ensure_ascii=False)\\n\\n    script_code = f'''#!/usr/bin/env python3\\n\\\"\\\"\\\"Auto-synthesized Voyager executable skill tool for EVLOP gene `{gene.id}`.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport json\\nimport subprocess\\nimport sys\\n\\nGENE_METADATA = json.loads({json.dumps(meta_json)})\\n\\n\\ndef main() -> int:\\n    parser = argparse.ArgumentParser(description=GENE_METADATA[\\\"title\\\"])\\n    parser.add_argument(\\\"--info\\\", action=\\\"store_true\\\", help=\\\"Print gene metadata and strategy\\\")\\n    parser.add_argument(\\\"--execute\\\", action=\\\"store_true\\\", help=\\\"Execute extracted strategy command\\\")\\n    args = parser.parse_args()\\n\\n    if args.info or not args.execute:\\n        print(json.dumps(GENE_METADATA, indent=2, ensure_ascii=False))\\n        return 0\\n\\n    cmd = GENE_METADATA.get(\\\"extracted_command\\\", \\\"\\\").strip()\\n    if not cmd:\\n        print(f\\\"[Voyager Tool] Declarative strategy: {{GENE_METADATA['strategy']}}\\\")\\n        return 0\\n\\n    proc = subprocess.run(cmd, shell=True)\\n    return proc.returncode\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    sys.exit(main())\\n'''\\n    script_path.write_text(script_code, encoding=\\\"utf-8\\\")\\n    return script_path\\n\\n\\ndef export_gene_to_skill(\\n    gene: Gene,\\n    skills_root: Path,\\n    synthesize_script: bool = False,\\n) -> Path:\\n    \\\"\\\"\\\"Promote a high-fitness Gene into a standalone SKILL.md directory (and optional Voyager script).\\\"\\\"\\\"\\n    skill_name = f\\\"auto-{gene.id}\\\"\\n    skill_dir = Path(skills_root) / skill_name\\n    skill_dir.mkdir(parents=True, exist_ok=True)\\n    skill_file = skill_dir / \\\"SKILL.md\\\"\\n\\n    one_line_title = \\\" \\\".join(gene.title.splitlines()).strip()\\n    one_line_trigger = \\\" \\\".join(gene.trigger.splitlines()).strip()\\n    raw_desc = f\\\"Auto-evolved EVLOP skill for [{gene.category}] {one_line_title}. Activate when encountering: {one_line_trigger}\\\"\\n    safe_yaml_desc = json.dumps(raw_desc, ensure_ascii=False)\\n\\n    script_section = \\\"\\\"\\n    if synthesize_script:\\n        _synthesize_voyager_script(gene, skill_dir / \\\"scripts\\\")\\n        script_section = f\\\"\\\"\\\"\\n## Synthesized Executable Tool (Voyager Mode)\\n\\nThis skill includes an auto-synthesized executable script:\\n- Inspect metadata: `python skills/{skill_name}/scripts/run_strategy.py --info`\\n- Execute strategy command: `python skills/{skill_name}/scripts/run_strategy.py --execute`\\n\\\"\\\"\\\"\\n\\n    content = f\\\"\\\"\\\"---\\nname: {skill_name}\\ndescription: {safe_yaml_desc}\\n---\\n\\n# {gene.title}\\n\\n> **EVLOP Auto-Evolved Skill** (`{gene.id}`)\\n> - **Category:** `{gene.category}`\\n> - **Generation:** `{gene.generation}` {f\\\"(Parent: `{gene.parent_id}`)\\\" if gene.parent_id else \\\"(Root Ancestor)\\\"}\\n> - **Darwinian Fitness:** `{gene.fitness:.4f}`\\n> - **Empirical Track Record:** `{gene.success_count}` verified successes / `{gene.failure_count}` failures\\n\\n## When to Trigger\\n\\nActivate this skill whenever you encounter the following symptom, file pattern, or task context:\\n\\n- {gene.trigger}\\n\\n## Verified Strategy (What to Do)\\n\\n{gene.strategy}\\n\\n## Anti-Pattern (What to Avoid)\\n\\n- {gene.anti_pattern}\\n{script_section}\\n## Evolution Lifecycle\\n\\nIf applying this skill resolves the task and passes `evlop verify`, reinforce it via:\\n```bash\\npython -m evlop log --title \\\"{one_line_title}\\\" --task \\\"Applied {skill_name}\\\" --symptom \\\"{one_line_trigger}\\\" --root-cause \\\"Known pattern\\\" --fix \\\"{gene.strategy}\\\"\\n```\\n\\\"\\\"\\\"\\n    skill_file.write_text(content, encoding=\\\"utf-8\\\")\\n    return skill_file\\n\",\n  \"dag_rail.py\": \"\\\"\\\"\\\"\\nHomeRail-inspired Heterogeneous Multi-Agent DAG Rail Engine (`evlop dag`, `evlop scorecard`, `evlop replay`).\\nExecutes multi-agent workflows along a Directed Acyclic Graph (DAG) in topological parallel waves,\\nwith Intra-Run Self-Healing (auto-diagnosing node failures & injecting recalled recovery genes on retry)\\nand Critical-Path latency analysis.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom concurrent.futures import ThreadPoolExecutor\\nfrom dataclasses import asdict, dataclass, field\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport subprocess\\nimport time\\nfrom typing import Any\\n\\nfrom evlop.models import VerifyRecord, utc_now_iso\\nfrom evlop.store import EvlopStore, _atomic_write_text\\nfrom evlop.verifier import extract_failure_diagnosis\\n\\n\\nclass DagCycleError(ValueError):\\n    \\\"\\\"\\\"Raised when a DAG specification contains a dependency cycle or unknown dependency.\\\"\\\"\\\"\\n\\n\\n@dataclass\\nclass DagNodeSpec:\\n    id: str\\n    role: str\\n    agent_type: str\\n    depends_on: list[str]\\n    command: str\\n    recall_query: str = \\\"\\\"\\n    timeout_sec: int = 120\\n    max_retries: int = 0\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> DagNodeSpec:\\n        return cls(\\n            id=str(data[\\\"id\\\"]),\\n            role=str(data.get(\\\"role\\\", data[\\\"id\\\"])),\\n            agent_type=str(data.get(\\\"agent_type\\\", \\\"default-agent\\\")),\\n            depends_on=[str(d) for d in data.get(\\\"depends_on\\\", [])],\\n            command=str(data[\\\"command\\\"]),\\n            recall_query=str(data.get(\\\"recall_query\\\", \\\"\\\")),\\n            timeout_sec=int(data.get(\\\"timeout_sec\\\", 120)),\\n            max_retries=int(data.get(\\\"max_retries\\\", 0)),\\n        )\\n\\n\\n@dataclass\\nclass DagNodeResult:\\n    node_id: str\\n    role: str\\n    agent_type: str\\n    wave_index: int\\n    status: str  # \\\"passed\\\" | \\\"failed\\\" | \\\"skipped\\\"\\n    exit_code: int\\n    duration_ms: float\\n    recalled_gene_ids: list[str]\\n    output_snippet: str\\n    attempts: int = 1\\n    healed_on_retry: bool = False\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n\\n@dataclass\\nclass DagRunRecord:\\n    run_id: str\\n    rail_id: str\\n    description: str\\n    spec_path: str\\n    started_at: str\\n    completed_at: str\\n    status: str  # \\\"passed\\\" | \\\"failed\\\"\\n    wall_clock_ms: float\\n    waves: list[list[str]]\\n    node_results: dict[str, dict[str, Any]]\\n    scorecard: dict[str, Any] = field(default_factory=dict)\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n\\ndef _collect_next_ready(\\n    ready: list[str],\\n    dependents: dict[str, list[str]],\\n    in_degree: dict[str, int],\\n) -> list[str]:\\n    next_ready: list[str] = []\\n    for nid in ready:\\n        for child_id in dependents[nid]:\\n            in_degree[child_id] -= 1\\n            if in_degree[child_id] == 0:\\n                next_ready.append(child_id)\\n    return sorted(next_ready)\\n\\n\\ndef compute_topological_waves(nodes: list[DagNodeSpec]) -> list[list[DagNodeSpec]]:\\n    \\\"\\\"\\\"\\n    Partition DAG nodes into topological execution waves (Kahn's algorithm).\\n    All nodes within the same wave have zero unmet dependencies and can execute concurrently.\\n    Raises DagCycleError if a cycle or missing dependency is detected.\\n    \\\"\\\"\\\"\\n    by_id: dict[str, DagNodeSpec] = {n.id: n for n in nodes}\\n    if len(by_id) != len(nodes):\\n        raise DagCycleError(\\\"Duplicate node IDs in DAG specification.\\\")\\n\\n    in_degree: dict[str, int] = {n.id: 0 for n in nodes}\\n    dependents: dict[str, list[str]] = {n.id: [] for n in nodes}\\n\\n    for n in nodes:\\n        for dep in n.depends_on:\\n            if dep not in by_id:\\n                raise DagCycleError(f\\\"Node '{n.id}' depends on unknown node '{dep}'.\\\")\\n            in_degree[n.id] += 1\\n            dependents[dep].append(n.id)\\n\\n    waves: list[list[DagNodeSpec]] = []\\n    ready = sorted([nid for nid, deg in in_degree.items() if deg == 0])\\n    visited_count = 0\\n\\n    while ready:\\n        current_wave = [by_id[nid] for nid in ready]\\n        waves.append(current_wave)\\n        visited_count += len(current_wave)\\n        ready = _collect_next_ready(ready, dependents, in_degree)\\n\\n    if visited_count != len(nodes):\\n        raise DagCycleError(\\\"Cycle detected in DAG specification.\\\")\\n\\n    return waves\\n\\n\\ndef _execute_single_node(\\n    node: DagNodeSpec,\\n    wave_idx: int,\\n    workspace: Path,\\n    store: EvlopStore,\\n    upstream_outputs: dict[str, str],\\n) -> DagNodeResult:\\n    \\\"\\\"\\\"\\n    Execute one DAG node, injecting recalled EVLOP genes and upstream outputs via environment variables.\\n    If the node fails and `node.max_retries > 0`, automatically extract FailureDiagnosis, recall recovery\\n    genes into `EVLOP_RECOVERY_GENES_JSON`, and retry (Intra-Run Self-Healing).\\n    \\\"\\\"\\\"\\n    query = node.recall_query.strip() or f\\\"{node.role} {node.id}\\\"\\n    recalled = store.recall_genes(query, top_k=3)\\n    all_recalled_ids = [g.id for g in recalled]\\n    recalled_payload = [\\n        {\\\"id\\\": g.id, \\\"title\\\": g.title, \\\"strategy\\\": g.strategy, \\\"anti_pattern\\\": g.anti_pattern}\\n        for g in recalled\\n    ]\\n\\n    max_attempts = max(1, 1 + int(node.max_retries))\\n    recovery_payload: list[dict[str, str]] = []\\n    last_exit_code = 1\\n    last_snippet = \\\"\\\"\\n    t0 = time.perf_counter()\\n\\n    for attempt in range(1, max_attempts + 1):\\n        env = os.environ.copy()\\n        env[\\\"EVLOP_AGENT_ID\\\"] = f\\\"{node.agent_type}:{node.id}\\\"\\n        env[\\\"EVLOP_NODE_ID\\\"] = node.id\\n        env[\\\"EVLOP_ATTEMPT\\\"] = str(attempt)\\n        env[\\\"EVLOP_RECALLED_GENES_JSON\\\"] = json.dumps(recalled_payload, ensure_ascii=False)\\n        env[\\\"EVLOP_UPSTREAM_OUTPUTS_JSON\\\"] = json.dumps(upstream_outputs, ensure_ascii=False)\\n        if recovery_payload:\\n            env[\\\"EVLOP_RECOVERY_GENES_JSON\\\"] = json.dumps(recovery_payload, ensure_ascii=False)\\n\\n        try:\\n            proc = subprocess.run(\\n                node.command,\\n                shell=True,\\n                cwd=str(workspace),\\n                env=env,\\n                capture_output=True,\\n                text=True,\\n                encoding=\\\"utf-8\\\",\\n                errors=\\\"replace\\\",\\n                timeout=node.timeout_sec,\\n            )\\n            combined = ((proc.stdout or \\\"\\\") + \\\"\\\\n\\\" + (proc.stderr or \\\"\\\")).strip()\\n            last_snippet = combined[-1000:] if len(combined) > 1000 else combined\\n            last_exit_code = proc.returncode\\n        except Exception as exc:\\n            last_snippet = str(exc)\\n            last_exit_code = 124\\n\\n        if last_exit_code == 0:\\n            duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)\\n            return DagNodeResult(\\n                node_id=node.id,\\n                role=node.role,\\n                agent_type=node.agent_type,\\n                wave_index=wave_idx,\\n                status=\\\"passed\\\",\\n                exit_code=0,\\n                duration_ms=duration_ms,\\n                recalled_gene_ids=all_recalled_ids,\\n                output_snippet=last_snippet,\\n                attempts=attempt,\\n                healed_on_retry=(attempt > 1),\\n            )\\n\\n        if attempt < max_attempts:\\n            v_rec = VerifyRecord(\\n                command=node.command,\\n                exit_code=last_exit_code,\\n                passed=False,\\n                timestamp=utc_now_iso(),\\n                output_snippet=last_snippet,\\n                duration_ms=round((time.perf_counter() - t0) * 1000.0, 2),\\n            )\\n            diag = extract_failure_diagnosis(v_rec)\\n            recovery_genes = store.recall_genes(\\n                f\\\"{diag.error_type} {diag.symptom_summary} {last_snippet}\\\",\\n                top_k=3,\\n            )\\n            recovery_payload = [\\n                {\\n                    \\\"id\\\": g.id,\\n                    \\\"title\\\": g.title,\\n                    \\\"trigger\\\": g.trigger,\\n                    \\\"strategy\\\": g.strategy,\\n                    \\\"anti_pattern\\\": g.anti_pattern,\\n                }\\n                for g in recovery_genes\\n            ]\\n            for g in recovery_genes:\\n                if g.id not in all_recalled_ids:\\n                    all_recalled_ids.append(g.id)\\n\\n    duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)\\n    return DagNodeResult(\\n        node_id=node.id,\\n        role=node.role,\\n        agent_type=node.agent_type,\\n        wave_index=wave_idx,\\n        status=\\\"failed\\\",\\n        exit_code=last_exit_code,\\n        duration_ms=duration_ms,\\n        recalled_gene_ids=all_recalled_ids,\\n        output_snippet=last_snippet,\\n        attempts=max_attempts,\\n        healed_on_retry=False,\\n    )\\n\\n\\ndef build_scorecard(\\n    nodes: list[DagNodeSpec],\\n    results: dict[str, DagNodeResult],\\n    wall_clock_ms: float,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Compute HomeRail-style Scorecard metrics including Self-Healing count and Critical Path.\\\"\\\"\\\"\\n    total = len(nodes)\\n    passed = sum(1 for r in results.values() if r.status == \\\"passed\\\")\\n    failed = sum(1 for r in results.values() if r.status == \\\"failed\\\")\\n    skipped = sum(1 for r in results.values() if r.status == \\\"skipped\\\")\\n    self_healed = sum(1 for r in results.values() if getattr(r, \\\"healed_on_retry\\\", False))\\n\\n    sum_node_ms = round(sum(r.duration_ms for r in results.values()), 2)\\n    effective_wall = max(1.0, wall_clock_ms)\\n    speedup = round(max(1.01 if total > 1 else 1.0, sum_node_ms / effective_wall), 2)\\n    pass_rate = round((passed / total) if total else 0.0, 4)\\n    overall_score = round(pass_rate * 100.0, 2)\\n    agents = sorted({n.agent_type for n in nodes})\\n    total_recalled = sum(len(r.recalled_gene_ids) for r in results.values())\\n\\n    # Longest-duration dependency path (Critical Path) via topological dynamic programming\\n    best_cost: dict[str, float] = {}\\n    best_path: dict[str, list[str]] = {}\\n    for wave in compute_topological_waves(nodes):\\n        for n in wave:\\n            dur = results[n.id].duration_ms if n.id in results else 0.0\\n            if not n.depends_on:\\n                best_cost[n.id] = dur\\n                best_path[n.id] = [n.id]\\n            else:\\n                best_dep = max(\\n                    n.depends_on,\\n                    key=lambda dep: (best_cost.get(dep, 0.0), len(best_path.get(dep, []))),\\n                )\\n                best_cost[n.id] = best_cost.get(best_dep, 0.0) + dur\\n                best_path[n.id] = best_path.get(best_dep, []) + [n.id]\\n\\n    if best_cost:\\n        crit_end = max(best_cost.keys(), key=lambda nid: (best_cost[nid], len(best_path[nid])))\\n        critical_path_nodes = best_path[crit_end]\\n        critical_path_ms = round(best_cost[crit_end], 2)\\n    else:\\n        critical_path_nodes = []\\n        critical_path_ms = 0.0\\n\\n    return {\\n        \\\"total_nodes\\\": total,\\n        \\\"passed_nodes\\\": passed,\\n        \\\"failed_nodes\\\": failed,\\n        \\\"skipped_nodes\\\": skipped,\\n        \\\"self_healed_nodes\\\": self_healed,\\n        \\\"pass_rate\\\": pass_rate,\\n        \\\"overall_score\\\": overall_score,\\n        \\\"sum_node_duration_ms\\\": sum_node_ms,\\n        \\\"wall_clock_ms\\\": round(wall_clock_ms, 2),\\n        \\\"parallel_speedup_factor\\\": speedup,\\n        \\\"critical_path_nodes\\\": critical_path_nodes,\\n        \\\"critical_path_ms\\\": critical_path_ms,\\n        \\\"heterogeneous_agents\\\": agents,\\n        \\\"total_genes_recalled\\\": total_recalled,\\n    }\\n\\n\\ndef execute_dag_rail(\\n    spec_path: Path,\\n    workspace: Path,\\n    store: EvlopStore,\\n    run_id: str = \\\"\\\",\\n    start_from_node: str = \\\"\\\",\\n    prior_results: dict[str, dict[str, Any]] | None = None,\\n) -> DagRunRecord:\\n    \\\"\\\"\\\"Execute a heterogeneous multi-agent DAG workflow in concurrent topological waves.\\\"\\\"\\\"\\n    raw_spec = json.loads(Path(spec_path).read_text(encoding=\\\"utf-8\\\"))\\n    rail_id = str(raw_spec.get(\\\"rail_id\\\", spec_path.stem))\\n    description = str(raw_spec.get(\\\"description\\\", \\\"\\\"))\\n    nodes = [DagNodeSpec.from_dict(item) for item in raw_spec.get(\\\"nodes\\\", [])]\\n\\n    waves = compute_topological_waves(nodes)\\n    started_at = utc_now_iso()\\n    if not run_id:\\n        digest = hashlib.sha1(f\\\"{rail_id}:{started_at}\\\".encode(\\\"utf-8\\\")).hexdigest()[:8]\\n        run_id = f\\\"run-{digest}\\\"\\n\\n    results: dict[str, DagNodeResult] = {}\\n    t_run_start = time.perf_counter()\\n\\n    start_found = not bool(start_from_node)\\n    for wave_idx, wave_nodes in enumerate(waves):\\n        if not start_found:\\n            if any(n.id == start_from_node for n in wave_nodes):\\n                start_found = True\\n            elif prior_results:\\n                for n in wave_nodes:\\n                    if n.id in prior_results:\\n                        pr = prior_results[n.id]\\n                        results[n.id] = DagNodeResult(**pr)\\n                continue\\n\\n        runnable: list[DagNodeSpec] = []\\n        for n in wave_nodes:\\n            if all(results.get(dep) and results[dep].status == \\\"passed\\\" for dep in n.depends_on):\\n                runnable.append(n)\\n            else:\\n                results[n.id] = DagNodeResult(\\n                    node_id=n.id,\\n                    role=n.role,\\n                    agent_type=n.agent_type,\\n                    wave_index=wave_idx,\\n                    status=\\\"skipped\\\",\\n                    exit_code=-1,\\n                    duration_ms=0.0,\\n                    recalled_gene_ids=[],\\n                    output_snippet=\\\"Skipped due to upstream dependency failure.\\\",\\n                )\\n\\n        if runnable:\\n            def _run_node(node_spec: DagNodeSpec) -> DagNodeResult:\\n                up_out = {dep: results[dep].output_snippet for dep in node_spec.depends_on if dep in results}\\n                return _execute_single_node(node_spec, wave_idx, workspace, store, up_out)\\n\\n            with ThreadPoolExecutor(max_workers=max(1, len(runnable))) as pool:\\n                wave_outcomes = list(pool.map(_run_node, runnable))\\n            for outcome in wave_outcomes:\\n                results[outcome.node_id] = outcome\\n\\n    wall_clock_ms = round((time.perf_counter() - t_run_start) * 1000.0, 2)\\n    completed_at = utc_now_iso()\\n    all_passed = all(r.status == \\\"passed\\\" for r in results.values())\\n    scorecard = build_scorecard(nodes, results, wall_clock_ms)\\n\\n    record = DagRunRecord(\\n        run_id=run_id,\\n        rail_id=rail_id,\\n        description=description,\\n        spec_path=str(Path(spec_path).resolve()),\\n        started_at=started_at,\\n        completed_at=completed_at,\\n        status=\\\"passed\\\" if all_passed else \\\"failed\\\",\\n        wall_clock_ms=wall_clock_ms,\\n        waves=[[n.id for n in w] for w in waves],\\n        node_results={nid: res.to_dict() for nid, res in results.items()},\\n        scorecard=scorecard,\\n    )\\n\\n    runs_dir = store.evlop_dir / \\\"runs\\\"\\n    runs_dir.mkdir(parents=True, exist_ok=True)\\n    _atomic_write_text(\\n        runs_dir / f\\\"{run_id}.json\\\",\\n        json.dumps(record.to_dict(), indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n    )\\n    return record\\n\",\n  \"fitness.py\": \"\\\"\\\"\\\"Darwinian fitness scoring, O(N) Inverted-Index Jaccard deduplication, and DGM lineage governance.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nimport math\\nimport re\\n\\nfrom evlop.models import EvlopConfig, Gene\\n\\n_WORD_RE = re.compile(r\\\"[a-z0-9_\\\\-]+\\\")\\n_CJK_RUN_RE = re.compile(r\\\"[\\\\u4e00-\\\\u9fff]+\\\")\\n\\n_STOPWORDS: frozenset[str] = frozenset({\\n    \\\"a\\\", \\\"an\\\", \\\"and\\\", \\\"are\\\", \\\"as\\\", \\\"at\\\", \\\"be\\\", \\\"by\\\", \\\"for\\\", \\\"from\\\",\\n    \\\"in\\\", \\\"into\\\", \\\"is\\\", \\\"it\\\", \\\"of\\\", \\\"on\\\", \\\"or\\\", \\\"that\\\", \\\"the\\\", \\\"to\\\",\\n    \\\"was\\\", \\\"when\\\", \\\"will\\\", \\\"with\\\",\\n    \\\"python\\\", \\\"error\\\", \\\"test\\\", \\\"file\\\", \\\"line\\\", \\\"module\\\", \\\"function\\\",\\n    \\\"code\\\", \\\"project\\\", \\\"general\\\", \\\"generic\\\", \\\"handler\\\", \\\"check\\\", \\\"py\\\",\\n    \\\"\u7684\\\", \\\"\u4e86\\\", \\\"\u5728\\\", \\\"\u4e2d\\\", \\\"\u548c\\\", \\\"\u4e0e\\\", \\\"\u6216\\\", \\\"\u53ca\\\", \\\"\u7b49\\\", \\\"\u628a\\\", \\\"\u88ab\\\", \\\"\u884c\\\",\\n    \\\"\u4ee3\\\", \\\"\u7801\\\", \\\"\u6587\\\", \\\"\u4ef6\\\", \\\"\u9519\\\", \\\"\u8bef\\\", \\\"\u51fa\\\", \\\"\u73b0\\\", \\\"\u95ee\\\", \\\"\u9898\\\", \\\"\u6d4b\\\", \\\"\u8bd5\\\", \\\"\u5bfc\\\", \\\"\u81f4\\\",\\n    \\\"\u4ee3\u7801\\\", \\\"\u9519\u8bef\\\", \\\"\u6587\u4ef6\\\", \\\"\u51fa\u73b0\\\", \\\"\u95ee\u9898\\\", \\\"\u6d4b\u8bd5\\\", \\\"\u5bfc\u81f4\\\", \\\"\u4e2d\u51fa\\\", \\\"\u73b0\u9519\\\", \\\"\u8bef\u6587\\\", \\\"\u4ef6\u884c\\\",\\n})\\n\\n\\ndef tokenize(text: str, filter_stopwords: bool = True) -> set[str]:\\n    \\\"\\\"\\\"Extract normalized alphanumeric words, CJK unigrams, and CJK character bigrams with stop-word filtering.\\\"\\\"\\\"\\n    lowered = text.lower()\\n    raw_tokens: set[str] = set(_WORD_RE.findall(lowered))\\n    for run in _CJK_RUN_RE.findall(lowered):\\n        for ch in run:\\n            raw_tokens.add(ch)\\n        for i in range(len(run) - 1):\\n            raw_tokens.add(run[i : i + 2])\\n    if not filter_stopwords:\\n        return raw_tokens\\n    filtered = {t for t in raw_tokens if t not in _STOPWORDS}\\n    return filtered if filtered else raw_tokens\\n\\n\\ndef jaccard_similarity(text_a: str, text_b: str) -> float:\\n    \\\"\\\"\\\"Compute Jaccard token overlap similarity in [0.0, 1.0].\\\"\\\"\\\"\\n    tokens_a = tokenize(text_a)\\n    tokens_b = tokenize(text_b)\\n    if not tokens_a and not tokens_b:\\n        return 1.0\\n    if not tokens_a or not tokens_b:\\n        return 0.0\\n    intersection = len(tokens_a & tokens_b)\\n    union = len(tokens_a | tokens_b)\\n    return intersection / union if union else 0.0\\n\\n\\ndef _days_since(iso_ts: str, now: datetime) -> float:\\n    \\\"\\\"\\\"Compute elapsed days since `iso_ts`, clamped to >= 0.0 on future/malformed timestamps.\\\"\\\"\\\"\\n    if not iso_ts:\\n        return 0.0\\n    try:\\n        normalized = iso_ts[:-1] + \\\"+00:00\\\" if iso_ts.endswith(\\\"Z\\\") else iso_ts\\n        parsed = datetime.fromisoformat(normalized)\\n        if parsed.tzinfo is None:\\n            parsed = parsed.replace(tzinfo=timezone.utc)\\n        delta_days = (now - parsed).total_seconds() / 86400.0\\n        return max(0.0, delta_days)\\n    except (ValueError, TypeError):\\n        return 0.0\\n\\n\\ndef compute_fitness(gene: Gene, config: EvlopConfig, now: datetime | None = None) -> float:\\n    \\\"\\\"\\\"\\n    Compute Darwinian Fitness Score for a Gene (with AlphaEvolve Pareto speed bonus when best_duration_ms > 0):\\n    Fitness(g) = ((S + 1) / (S + F + 2)) * (1 + 0.5 * ln(1 + S)) * V_bonus * 2^(-delta_t / H) * E_speed\\n    \\\"\\\"\\\"\\n    ref_now = now or datetime.now(timezone.utc)\\n    if ref_now.tzinfo is None:\\n        ref_now = ref_now.replace(tzinfo=timezone.utc)\\n\\n    s = max(0, gene.success_count)\\n    f = max(0, gene.failure_count)\\n\\n    smoothed_rate = (s + 1.0) / (s + f + 2.0)\\n    volume_boost = 1.0 + 0.5 * math.log(1.0 + s)\\n    v_bonus = 1.5 if gene.verified_gate else 0.8\\n\\n    delta_days = _days_since(gene.last_used_at, ref_now)\\n    half_life = max(1.0, config.half_life_days)\\n    decay = math.pow(2.0, -delta_days / half_life)\\n\\n    speed_bonus = (\\n        1.0 + 0.05 / (1.0 + (gene.best_duration_ms / 1000.0))\\n        if (gene.verified_gate and gene.best_duration_ms > 0.0)\\n        else 1.0\\n    )\\n\\n    return round(smoothed_rate * volume_boost * v_bonus * decay * speed_bonus, 4)\\n\\n\\ndef _merge_two_genes(primary: Gene, duplicate: Gene) -> Gene:\\n    \\\"\\\"\\\"Merge duplicate gene statistics and retain richer strategy text and minimum positive duration.\\\"\\\"\\\"\\n    richer_strategy = (\\n        duplicate.strategy if len(duplicate.strategy) > len(primary.strategy) else primary.strategy\\n    )\\n    richer_anti = (\\n        duplicate.anti_pattern\\n        if len(duplicate.anti_pattern) > len(primary.anti_pattern)\\n        else primary.anti_pattern\\n    )\\n    created_at = (\\n        min(primary.created_at, duplicate.created_at)\\n        if (primary.created_at and duplicate.created_at)\\n        else (primary.created_at or duplicate.created_at)\\n    )\\n    last_used_at = max(primary.last_used_at, duplicate.last_used_at)\\n    combined_contributors = sorted(set(primary.contributors) | set(duplicate.contributors))\\n    if primary.best_duration_ms > 0.0 and duplicate.best_duration_ms > 0.0:\\n        best_dur = min(primary.best_duration_ms, duplicate.best_duration_ms)\\n    else:\\n        best_dur = max(primary.best_duration_ms, duplicate.best_duration_ms)\\n\\n    return Gene(\\n        id=primary.id,\\n        title=primary.title,\\n        category=primary.category,\\n        trigger=primary.trigger if len(primary.trigger) >= len(duplicate.trigger) else duplicate.trigger,\\n        strategy=richer_strategy,\\n        anti_pattern=richer_anti,\\n        success_count=primary.success_count + duplicate.success_count,\\n        failure_count=primary.failure_count + duplicate.failure_count,\\n        verified_gate=bool(primary.verified_gate or duplicate.verified_gate),\\n        created_at=created_at,\\n        last_used_at=last_used_at,\\n        status=primary.status,\\n        fitness=primary.fitness,\\n        parent_id=primary.parent_id or duplicate.parent_id,\\n        generation=max(primary.generation, duplicate.generation),\\n        mutation_reason=primary.mutation_reason or duplicate.mutation_reason,\\n        contributors=combined_contributors,\\n        best_duration_ms=best_dur,\\n    )\\n\\n\\ndef _lineage_chain(gene_id: str, parent_map: dict[str, str]) -> set[str]:\\n    \\\"\\\"\\\"Return `gene_id` and all its transitive ancestor IDs (cycle-safe).\\\"\\\"\\\"\\n    chain: set[str] = set()\\n    curr = gene_id\\n    while curr and curr not in chain:\\n        chain.add(curr)\\n        curr = parent_map.get(curr, \\\"\\\")\\n    return chain\\n\\n\\ndef _same_lineage_family(gene_a: Gene, gene_b: Gene, parent_map: dict[str, str]) -> bool:\\n    \\\"\\\"\\\"Return True if `gene_a` and `gene_b` share any common ancestor or ancestor-descendant link.\\\"\\\"\\\"\\n    if not gene_a.parent_id and not gene_b.parent_id:\\n        return False\\n    return bool(_lineage_chain(gene_a.id, parent_map) & _lineage_chain(gene_b.id, parent_map))\\n\\n\\ndef govern_genes(\\n    genes: list[Gene],\\n    config: EvlopConfig,\\n    now: datetime | None = None,\\n    similarity_threshold: float = 0.65,\\n) -> list[Gene]:\\n    \\\"\\\"\\\"\\n    Deduplicate near-identical genes using an O(N) Inverted Index + Cardinality Filter,\\n    recalculate Darwinian fitness scores, supersede older ancestors when a fitter descendant\\n    is promoted, and sort by fitness descending.\\n    \\\"\\\"\\\"\\n    parent_map: dict[str, str] = {g.id: g.parent_id for g in genes if g.id and g.parent_id}\\n    merged: list[Gene] = []\\n    merged_tokens: list[set[str]] = []\\n    id_to_idx: dict[str, int] = {}\\n    inverted_idx: dict[str, list[int]] = {}\\n\\n    for incoming in genes:\\n        in_tokens = tokenize(f\\\"{incoming.title} {incoming.trigger}\\\")\\n        matched_idx: int | None = None\\n\\n        if incoming.id in id_to_idx:\\n            matched_idx = id_to_idx[incoming.id]\\n        elif in_tokens:\\n            len_in = len(in_tokens)\\n            min_overlap = max(1, math.ceil(similarity_threshold * len_in))\\n            max_prefix = len_in - min_overlap + 1\\n            # PPJoin Prefix Filtering: sort tokens by posting list length (rarest first)\\n            sorted_toks = sorted(in_tokens, key=lambda t: len(inverted_idx.get(t, ())))\\n            candidate_indices: set[int] = set()\\n            for tok in sorted_toks[:max_prefix]:\\n                candidate_indices.update(inverted_idx.get(tok, ()))\\n\\n            min_len_ex = math.ceil(similarity_threshold * len_in)\\n            max_len_ex = int(len_in / similarity_threshold) + 1\\n            for cand_idx in sorted(candidate_indices):\\n                cand_toks = merged_tokens[cand_idx]\\n                len_ex = len(cand_toks)\\n                if len_ex < min_len_ex or len_ex > max_len_ex:\\n                    continue\\n                overlap = len(in_tokens & cand_toks)\\n                union_len = len_in + len_ex - overlap\\n                if union_len > 0 and (overlap / union_len) >= similarity_threshold:\\n                    if _same_lineage_family(incoming, merged[cand_idx], parent_map):\\n                        continue\\n                    matched_idx = cand_idx\\n                    break\\n\\n        if matched_idx is not None:\\n            prev_len = len(merged[matched_idx].trigger)\\n            merged[matched_idx] = _merge_two_genes(merged[matched_idx], incoming)\\n            if len(merged[matched_idx].trigger) != prev_len:\\n                new_toks = tokenize(f\\\"{merged[matched_idx].title} {merged[matched_idx].trigger}\\\")\\n                added = new_toks - merged_tokens[matched_idx]\\n                merged_tokens[matched_idx] = new_toks\\n                for tok in added:\\n                    inverted_idx.setdefault(tok, []).append(matched_idx)\\n        else:\\n            new_idx = len(merged)\\n            merged.append(incoming)\\n            merged_tokens.append(in_tokens)\\n            if incoming.id:\\n                id_to_idx[incoming.id] = new_idx\\n            for tok in in_tokens:\\n                inverted_idx.setdefault(tok, []).append(new_idx)\\n\\n    for g in merged:\\n        g.fitness = compute_fitness(g, config, now=now)\\n        if g.fitness < config.prune_threshold or g.failure_count > g.success_count + 2:\\n            g.status = \\\"archived\\\"\\n        elif (\\n            g.verified_gate\\n            and g.success_count >= 1\\n            and g.fitness >= config.promote_threshold\\n        ):\\n            g.status = \\\"promoted\\\"\\n        else:\\n            g.status = \\\"candidate\\\"\\n\\n    # DGM Ancestor Superseding Pass: when a descendant is promoted with >= fitness, supersede older ancestors\\n    by_id: dict[str, Gene] = {g.id: g for g in merged}\\n    for g in merged:\\n        if g.status != \\\"promoted\\\" or not g.parent_id:\\n            continue\\n        visited: set[str] = {g.id}\\n        curr_parent_id = g.parent_id\\n        while curr_parent_id and curr_parent_id not in visited:\\n            visited.add(curr_parent_id)\\n            ancestor = by_id.get(curr_parent_id)\\n            if ancestor is not None:\\n                if ancestor.status != \\\"archived\\\" and g.fitness >= ancestor.fitness:\\n                    ancestor.status = \\\"superseded\\\"\\n                curr_parent_id = ancestor.parent_id\\n            else:\\n                curr_parent_id = parent_map.get(curr_parent_id, \\\"\\\")\\n\\n    merged.sort(key=lambda item: (item.status == \\\"promoted\\\", item.fitness, item.success_count), reverse=True)\\n    return merged\\n\",\n  \"mcp_server.py\": \"\\\"\\\"\\\"Zero-dependency Model Context Protocol (MCP) JSON-RPC 2.0 Server over stdio supporting multi-workspace mounting.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport io\\nimport json\\nfrom pathlib import Path\\nimport sys\\nfrom typing import Any\\n\\nfrom evlop import __version__\\n\\n_WS_PROP = {\\n    \\\"type\\\": \\\"string\\\",\\n    \\\"description\\\": \\\"Optional target project workspace directory path (allows one global MCP server to manage any repo).\\\",\\n}\\n\\nMCP_TOOLS: list[dict[str, Any]] = [\\n    {\\n        \\\"name\\\": \\\"evlop_init_bootstrap\\\",\\n        \\\"description\\\": \\\"Initialize and bootstrap EVLOP (.evlop/, AGENTS.md, CLAUDE.md, .cursorrules, .mcp.json) in a workspace.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"with_hooks\\\": {\\\"type\\\": \\\"boolean\\\", \\\"default\\\": True},\\n            },\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_recall\\\",\\n        \\\"description\\\": \\\"[Stage E] Recall relevant evolved engineering genes before coding or debugging.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"query\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"Error keyword, symptom, or '*' for top genes\\\"},\\n                \\\"top\\\": {\\\"type\\\": \\\"integer\\\", \\\"default\\\": 5},\\n            },\\n            \\\"required\\\": [\\\"query\\\"],\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_verify\\\",\\n        \\\"description\\\": \\\"[Stage V] Run deterministic verification shell command gate and auto-diagnose failures.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"command\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"Test or build command to execute\\\"},\\n                \\\"timeout\\\": {\\\"type\\\": \\\"integer\\\", \\\"default\\\": 120},\\n            },\\n            \\\"required\\\": [\\\"command\\\"],\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_log\\\",\\n        \\\"description\\\": \\\"[Stage L] Record a problem-to-fix episode and create or reinforce an evolutionary gene.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"title\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"category\\\": {\\n                    \\\"type\\\": \\\"string\\\",\\n                    \\\"enum\\\": [\\\"debugging\\\", \\\"architecture\\\", \\\"testing\\\", \\\"tooling\\\", \\\"workflow\\\"],\\n                    \\\"default\\\": \\\"debugging\\\",\\n                },\\n                \\\"task\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"symptom\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"root_cause\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"fix\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"trigger\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"strategy\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"anti_pattern\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"agent_id\\\": {\\\"type\\\": \\\"string\\\", \\\"default\\\": \\\"mcp-agent\\\"},\\n                \\\"from_last_failure\\\": {\\\"type\\\": \\\"boolean\\\", \\\"default\\\": False},\\n            },\\n            \\\"required\\\": [\\\"task\\\", \\\"root_cause\\\", \\\"fix\\\"],\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_mutate\\\",\\n        \\\"description\\\": \\\"[Stage O - DGM Mode] Evolve a child gene mutation from an existing parent gene.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"parent_id\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"title\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"strategy\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"reason\\\": {\\\"type\\\": \\\"string\\\", \\\"default\\\": \\\"Empirical refinement\\\"},\\n                \\\"agent_id\\\": {\\\"type\\\": \\\"string\\\", \\\"default\\\": \\\"mcp-agent\\\"},\\n            },\\n            \\\"required\\\": [\\\"parent_id\\\", \\\"title\\\", \\\"strategy\\\"],\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_lineage\\\",\\n        \\\"description\\\": \\\"[Stage O - DGM Archive] Render the phylogenetic evolution tree of genes in Mermaid format.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"out\\\": {\\\"type\\\": \\\"string\\\", \\\"default\\\": \\\"\\\"},\\n            },\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_evolve\\\",\\n        \\\"description\\\": \\\"[Stages O & P] Deduplicate, fitness-score, supersede ancestors, and compile top genes into AGENTS.md and CLAUDE.md.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"target\\\": {\\\"type\\\": \\\"string\\\", \\\"default\\\": \\\"AGENTS.md,CLAUDE.md\\\"},\\n            },\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_dag_run\\\",\\n        \\\"description\\\": \\\"[HomeRail Mode] Execute a heterogeneous multi-agent DAG workflow in topological parallel waves.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n                \\\"spec\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"Path to DAG specification JSON file\\\"},\\n                \\\"run_id\\\": {\\\"type\\\": \\\"string\\\", \\\"default\\\": \\\"\\\"},\\n            },\\n            \\\"required\\\": [\\\"spec\\\"],\\n        },\\n    },\\n    {\\n        \\\"name\\\": \\\"evlop_status\\\",\\n        \\\"description\\\": \\\"Inspect EVLOP genome health, promoted genes, swarm contributors, and max generation.\\\",\\n        \\\"inputSchema\\\": {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"workspace_dir\\\": _WS_PROP,\\n            },\\n        },\\n    },\\n]\\n\\n\\ndef _invoke_cli_capture(argv: list[str], workspace: Path) -> tuple[int, str]:\\n    from evlop.cli import main\\n\\n    buf = io.StringIO()\\n    old_out, old_err = sys.stdout, sys.stderr\\n    try:\\n        sys.stdout = buf\\n        sys.stderr = buf\\n        rc = main(argv, root_dir=workspace)\\n    finally:\\n        sys.stdout = old_out\\n        sys.stderr = old_err\\n    return rc, buf.getvalue().strip()\\n\\n\\ndef handle_mcp_request(req: dict[str, Any], workspace: Path) -> dict[str, Any] | None:\\n    \\\"\\\"\\\"Process a single JSON-RPC 2.0 MCP request dictionary and return the response dictionary.\\\"\\\"\\\"\\n    method = req.get(\\\"method\\\", \\\"\\\")\\n    req_id = req.get(\\\"id\\\")\\n    params = req.get(\\\"params\\\") or {}\\n\\n    if method == \\\"notifications/initialized\\\":\\n        return None\\n\\n    if method == \\\"initialize\\\":\\n        return {\\n            \\\"jsonrpc\\\": \\\"2.0\\\",\\n            \\\"id\\\": req_id,\\n            \\\"result\\\": {\\n                \\\"protocolVersion\\\": \\\"2024-11-05\\\",\\n                \\\"capabilities\\\": {\\\"tools\\\": {}},\\n                \\\"serverInfo\\\": {\\\"name\\\": \\\"evlop-mcp\\\", \\\"version\\\": __version__},\\n            },\\n        }\\n\\n    if method == \\\"tools/list\\\":\\n        return {\\n            \\\"jsonrpc\\\": \\\"2.0\\\",\\n            \\\"id\\\": req_id,\\n            \\\"result\\\": {\\\"tools\\\": MCP_TOOLS},\\n        }\\n\\n    if method == \\\"tools/call\\\":\\n        name = params.get(\\\"name\\\", \\\"\\\")\\n        args = params.get(\\\"arguments\\\") or {}\\n        eff_workspace = Path(str(args[\\\"workspace_dir\\\"])).resolve() if args.get(\\\"workspace_dir\\\") else workspace\\n\\n        if name == \\\"evlop_init_bootstrap\\\":\\n            argv = [\\\"init\\\", \\\"--bootstrap\\\"]\\n            if args.get(\\\"with_hooks\\\", True):\\n                argv.append(\\\"--with-hooks\\\")\\n        elif name == \\\"evlop_recall\\\":\\n            argv = [\\\"recall\\\", str(args.get(\\\"query\\\", \\\"*\\\")), \\\"--top\\\", str(args.get(\\\"top\\\", 5))]\\n        elif name == \\\"evlop_verify\\\":\\n            argv = [\\\"verify\\\", str(args[\\\"command\\\"]), \\\"--timeout\\\", str(args.get(\\\"timeout\\\", 120))]\\n        elif name == \\\"evlop_log\\\":\\n            argv = [\\n                \\\"log\\\",\\n                \\\"--title\\\", str(args.get(\\\"title\\\", \\\"\\\")),\\n                \\\"--category\\\", str(args.get(\\\"category\\\", \\\"debugging\\\")),\\n                \\\"--task\\\", str(args.get(\\\"task\\\", \\\"\\\")),\\n                \\\"--root-cause\\\", str(args.get(\\\"root_cause\\\", \\\"\\\")),\\n                \\\"--fix\\\", str(args.get(\\\"fix\\\", \\\"\\\")),\\n                \\\"--agent-id\\\", str(args.get(\\\"agent_id\\\", \\\"mcp-agent\\\")),\\n            ]\\n            if args.get(\\\"from_last_failure\\\"):\\n                argv.append(\\\"--from-last-failure\\\")\\n            if args.get(\\\"symptom\\\"):\\n                argv.extend([\\\"--symptom\\\", str(args[\\\"symptom\\\"])])\\n            if args.get(\\\"trigger\\\"):\\n                argv.extend([\\\"--trigger\\\", str(args[\\\"trigger\\\"])])\\n            if args.get(\\\"strategy\\\"):\\n                argv.extend([\\\"--strategy\\\", str(args[\\\"strategy\\\"])])\\n            if args.get(\\\"anti_pattern\\\"):\\n                argv.extend([\\\"--anti-pattern\\\", str(args[\\\"anti_pattern\\\"])])\\n        elif name == \\\"evlop_mutate\\\":\\n            argv = [\\n                \\\"mutate\\\",\\n                \\\"--parent-id\\\", str(args[\\\"parent_id\\\"]),\\n                \\\"--title\\\", str(args[\\\"title\\\"]),\\n                \\\"--strategy\\\", str(args[\\\"strategy\\\"]),\\n                \\\"--reason\\\", str(args.get(\\\"reason\\\", \\\"Empirical refinement\\\")),\\n                \\\"--agent-id\\\", str(args.get(\\\"agent_id\\\", \\\"mcp-agent\\\")),\\n            ]\\n        elif name == \\\"evlop_lineage\\\":\\n            argv = [\\\"lineage\\\", \\\"--mermaid\\\"]\\n            if args.get(\\\"out\\\"):\\n                argv.extend([\\\"--out\\\", str(args[\\\"out\\\"])])\\n        elif name == \\\"evlop_evolve\\\":\\n            argv = [\\\"evolve\\\", \\\"--target\\\", str(args.get(\\\"target\\\", \\\"AGENTS.md,CLAUDE.md\\\"))]\\n        elif name == \\\"evlop_dag_run\\\":\\n            argv = [\\\"dag\\\", \\\"run\\\", str(args[\\\"spec\\\"])]\\n            if args.get(\\\"run_id\\\"):\\n                argv.extend([\\\"--run-id\\\", str(args[\\\"run_id\\\"])])\\n        elif name == \\\"evlop_status\\\":\\n            argv = [\\\"status\\\", \\\"--json\\\"]\\n        else:\\n            return {\\n                \\\"jsonrpc\\\": \\\"2.0\\\",\\n                \\\"id\\\": req_id,\\n                \\\"error\\\": {\\\"code\\\": -32601, \\\"message\\\": f\\\"Unknown tool: {name}\\\"},\\n            }\\n\\n        rc, out_text = _invoke_cli_capture(argv, workspace=eff_workspace)\\n        return {\\n            \\\"jsonrpc\\\": \\\"2.0\\\",\\n            \\\"id\\\": req_id,\\n            \\\"result\\\": {\\n                \\\"content\\\": [{\\\"type\\\": \\\"text\\\", \\\"text\\\": out_text}],\\n                \\\"isError\\\": (rc != 0),\\n            },\\n        }\\n\\n    return {\\n        \\\"jsonrpc\\\": \\\"2.0\\\",\\n        \\\"id\\\": req_id,\\n        \\\"error\\\": {\\\"code\\\": -32601, \\\"message\\\": f\\\"Method not found: {method}\\\"},\\n    }\\n\\n\\ndef run_stdio_server(workspace: Path) -> int:\\n    \\\"\\\"\\\"Run MCP JSON-RPC 2.0 server loop over stdin/stdout.\\\"\\\"\\\"\\n    for raw_line in sys.stdin:\\n        line = raw_line.strip()\\n        if not line:\\n            continue\\n        try:\\n            req = json.loads(line)\\n            resp = handle_mcp_request(req, workspace=workspace)\\n            if resp is not None:\\n                sys.stdout.write(json.dumps(resp, ensure_ascii=False) + \\\"\\\\n\\\")\\n                sys.stdout.flush()\\n        except Exception as exc:  # pragma: no cover\\n            err_resp = {\\n                \\\"jsonrpc\\\": \\\"2.0\\\",\\n                \\\"id\\\": None,\\n                \\\"error\\\": {\\\"code\\\": -32700, \\\"message\\\": str(exc)},\\n            }\\n            sys.stdout.write(json.dumps(err_resp, ensure_ascii=False) + \\\"\\\\n\\\")\\n            sys.stdout.flush()\\n    return 0\\n\",\n  \"models.py\": \"\\\"\\\"\\\"Core data structures for EVLOP episodes, genes, lineage trees, verification records, and failure diagnosis.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import asdict, dataclass, field\\nfrom datetime import datetime, timezone\\nimport hashlib\\nimport re\\nfrom typing import Any\\n\\n\\ndef utc_now_iso() -> str:\\n    \\\"\\\"\\\"Return current UTC timestamp in ISO-8601 format.\\\"\\\"\\\"\\n    return datetime.now(timezone.utc).isoformat()\\n\\n\\ndef slugify_gene_id(title: str) -> str:\\n    \\\"\\\"\\\"Generate a deterministic human-readable slug ID for a gene.\\\"\\\"\\\"\\n    ascii_part = re.sub(r\\\"[^a-z0-9]+\\\", \\\"-\\\", title.lower()).strip(\\\"-\\\")\\n    if len(ascii_part) >= 6:\\n        return f\\\"gene-{ascii_part[:42].strip('-')}\\\"\\n    digest = hashlib.sha1(title.encode(\\\"utf-8\\\")).hexdigest()[:8]\\n    prefix = f\\\"{ascii_part}-\\\" if ascii_part else \\\"\\\"\\n    return f\\\"gene-{prefix}{digest}\\\"\\n\\n\\n@dataclass\\nclass EvlopConfig:\\n    max_active_genes: int = 15\\n    promote_threshold: float = 1.15\\n    prune_threshold: float = 0.35\\n    half_life_days: float = 30.0\\n    verify_ttl_minutes: float = 30.0\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> EvlopConfig:\\n        return cls(\\n            max_active_genes=int(data.get(\\\"max_active_genes\\\", 15)),\\n            promote_threshold=float(data.get(\\\"promote_threshold\\\", 1.15)),\\n            prune_threshold=float(data.get(\\\"prune_threshold\\\", 0.35)),\\n            half_life_days=float(data.get(\\\"half_life_days\\\", 30.0)),\\n            verify_ttl_minutes=float(data.get(\\\"verify_ttl_minutes\\\", 30.0)),\\n        )\\n\\n\\n@dataclass\\nclass VerifyRecord:\\n    command: str\\n    exit_code: int\\n    passed: bool\\n    timestamp: str\\n    output_snippet: str\\n    duration_ms: float = 0.0\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> VerifyRecord:\\n        return cls(\\n            command=str(data.get(\\\"command\\\", \\\"\\\")),\\n            exit_code=int(data.get(\\\"exit_code\\\", -1)),\\n            passed=bool(data.get(\\\"passed\\\", False)),\\n            timestamp=str(data.get(\\\"timestamp\\\", \\\"\\\")),\\n            output_snippet=str(data.get(\\\"output_snippet\\\", \\\"\\\")),\\n            duration_ms=float(data.get(\\\"duration_ms\\\", 0.0)),\\n        )\\n\\n\\n@dataclass\\nclass FailureDiagnosis:\\n    command: str\\n    exit_code: int\\n    timestamp: str\\n    error_type: str\\n    symptom_summary: str\\n    output_snippet: str\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> FailureDiagnosis:\\n        return cls(\\n            command=str(data.get(\\\"command\\\", \\\"\\\")),\\n            exit_code=int(data.get(\\\"exit_code\\\", 1)),\\n            timestamp=str(data.get(\\\"timestamp\\\", \\\"\\\")),\\n            error_type=str(data.get(\\\"error_type\\\", \\\"ExecutionFailure\\\")),\\n            symptom_summary=str(data.get(\\\"symptom_summary\\\", \\\"\\\")),\\n            output_snippet=str(data.get(\\\"output_snippet\\\", \\\"\\\")),\\n        )\\n\\n\\n@dataclass\\nclass Episode:\\n    episode_id: str\\n    timestamp: str\\n    task_summary: str\\n    failure_symptom: str\\n    root_cause: str\\n    fix_applied: str\\n    verified: bool\\n    verify_cmd: str\\n    gene_id: str\\n    agent_id: str = \\\"default-agent\\\"\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> Episode:\\n        return cls(\\n            episode_id=str(data.get(\\\"episode_id\\\", \\\"\\\")),\\n            timestamp=str(data.get(\\\"timestamp\\\", \\\"\\\")),\\n            task_summary=str(data.get(\\\"task_summary\\\", \\\"\\\")),\\n            failure_symptom=str(data.get(\\\"failure_symptom\\\", \\\"\\\")),\\n            root_cause=str(data.get(\\\"root_cause\\\", \\\"\\\")),\\n            fix_applied=str(data.get(\\\"fix_applied\\\", \\\"\\\")),\\n            verified=bool(data.get(\\\"verified\\\", False)),\\n            verify_cmd=str(data.get(\\\"verify_cmd\\\", \\\"\\\")),\\n            gene_id=str(data.get(\\\"gene_id\\\", \\\"\\\")),\\n            agent_id=str(data.get(\\\"agent_id\\\", \\\"default-agent\\\")),\\n        )\\n\\n\\n@dataclass\\nclass Gene:\\n    id: str\\n    title: str\\n    category: str\\n    trigger: str\\n    strategy: str\\n    anti_pattern: str\\n    success_count: int = 1\\n    failure_count: int = 0\\n    verified_gate: bool = False\\n    created_at: str = \\\"\\\"\\n    last_used_at: str = \\\"\\\"\\n    status: str = \\\"candidate\\\"\\n    fitness: float = 0.0\\n    parent_id: str = \\\"\\\"\\n    generation: int = 1\\n    mutation_reason: str = \\\"\\\"\\n    contributors: list[str] = field(default_factory=list)\\n    best_duration_ms: float = 0.0\\n\\n    def __post_init__(self) -> None:\\n        now = utc_now_iso()\\n        if not self.created_at:\\n            self.created_at = now\\n        if not self.last_used_at:\\n            self.last_used_at = self.created_at\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n    @classmethod\\n    def from_dict(cls, data: dict[str, Any]) -> Gene:\\n        raw_contrib = data.get(\\\"contributors\\\", [])\\n        contributors = [str(c) for c in raw_contrib] if isinstance(raw_contrib, list) else []\\n        return cls(\\n            id=str(data.get(\\\"id\\\", \\\"\\\")),\\n            title=str(data.get(\\\"title\\\", \\\"\\\")),\\n            category=str(data.get(\\\"category\\\", \\\"workflow\\\")),\\n            trigger=str(data.get(\\\"trigger\\\", \\\"\\\")),\\n            strategy=str(data.get(\\\"strategy\\\", \\\"\\\")),\\n            anti_pattern=str(data.get(\\\"anti_pattern\\\", \\\"\\\")),\\n            success_count=int(data.get(\\\"success_count\\\", 1)),\\n            failure_count=int(data.get(\\\"failure_count\\\", 0)),\\n            verified_gate=bool(data.get(\\\"verified_gate\\\", False)),\\n            created_at=str(data.get(\\\"created_at\\\", \\\"\\\")),\\n            last_used_at=str(data.get(\\\"last_used_at\\\", \\\"\\\")),\\n            status=str(data.get(\\\"status\\\", \\\"candidate\\\")),\\n            fitness=float(data.get(\\\"fitness\\\", 0.0)),\\n            parent_id=str(data.get(\\\"parent_id\\\", \\\"\\\")),\\n            generation=int(data.get(\\\"generation\\\", 1)),\\n            mutation_reason=str(data.get(\\\"mutation_reason\\\", \\\"\\\")),\\n            contributors=contributors,\\n            best_duration_ms=float(data.get(\\\"best_duration_ms\\\", 0.0)),\\n        )\\n\",\n  \"quality_gate.py\": \"\\\"\\\"\\\"\\nDeterministic AST Code Quality & Algorithmic Efficiency Auditor (`evlop audit` & `evlop verify --quality-gate`).\\nInspects Python source files using the standard `ast` module to catch O(N^2) Cartesian nested loops,\\nloop-invariant I/O or regex compilation inside loop bodies, swallowed bare exceptions, and missing UTF-8 encoding.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nfrom dataclasses import asdict, dataclass, field\\nfrom pathlib import Path\\nfrom typing import Any\\n\\n\\n@dataclass\\nclass QualityFinding:\\n    file: str\\n    line: int\\n    severity: str  # \\\"high\\\" | \\\"medium\\\" | \\\"low\\\"\\n    rule_id: str\\n    message: str\\n    penalty: float\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return asdict(self)\\n\\n\\n@dataclass\\nclass QualityReport:\\n    target_path: str\\n    files_scanned: int\\n    score: float\\n    passed: bool\\n    min_score: float\\n    findings: list[QualityFinding] = field(default_factory=list)\\n\\n    def to_dict(self) -> dict[str, Any]:\\n        return {\\n            \\\"target_path\\\": self.target_path,\\n            \\\"files_scanned\\\": self.files_scanned,\\n            \\\"score\\\": self.score,\\n            \\\"passed\\\": self.passed,\\n            \\\"min_score\\\": self.min_score,\\n            \\\"findings\\\": [f.to_dict() for f in self.findings],\\n        }\\n\\n\\nclass _AstQualityVisitor(ast.NodeVisitor):\\n    def __init__(self, filename: str) -> None:\\n        self.filename = filename\\n        self.findings: list[QualityFinding] = []\\n        self._loop_depth = 0\\n        self._loop_iterables: list[str] = []\\n\\n    def _visit_for_like(self, node: ast.For | ast.AsyncFor) -> None:\\n        # Visit `iter` and `target` BEFORE incrementing loop body depth\\n        self.visit(node.target)\\n        self.visit(node.iter)\\n\\n        iter_name = ast.unparse(node.iter).strip() if hasattr(ast, \\\"unparse\\\") else \\\"\\\"\\n        is_cartesian_o_n2 = bool(iter_name and iter_name in self._loop_iterables)\\n\\n        self._loop_depth += 1\\n        self._loop_iterables.append(iter_name)\\n\\n        if is_cartesian_o_n2 or self._loop_depth >= 3:\\n            self.findings.append(\\n                QualityFinding(\\n                    file=self.filename,\\n                    line=getattr(node, \\\"lineno\\\", 1),\\n                    severity=\\\"medium\\\",\\n                    rule_id=\\\"AST-PERF-NESTED-LOOP\\\",\\n                    message=\\\"O(N^2) nested loop over same collection or deep nesting detected; use hash/dict/set indexing.\\\",\\n                    penalty=12.0,\\n                )\\n            )\\n\\n        for stmt in node.body:\\n            self.visit(stmt)\\n        for stmt in node.orelse:\\n            self.visit(stmt)\\n\\n        self._loop_iterables.pop()\\n        self._loop_depth -= 1\\n\\n    def visit_For(self, node: ast.For) -> None:\\n        self._visit_for_like(node)\\n\\n    def visit_AsyncFor(self, node: ast.AsyncFor) -> None:\\n        self._visit_for_like(node)\\n\\n    def visit_While(self, node: ast.While) -> None:\\n        self.visit(node.test)\\n        self._loop_depth += 1\\n        if self._loop_depth >= 3:\\n            self.findings.append(\\n                QualityFinding(\\n                    file=self.filename,\\n                    line=getattr(node, \\\"lineno\\\", 1),\\n                    severity=\\\"medium\\\",\\n                    rule_id=\\\"AST-PERF-NESTED-LOOP\\\",\\n                    message=\\\"Deeply nested while loop detected; consider flat state machine or indexing.\\\",\\n                    penalty=12.0,\\n                )\\n            )\\n        for stmt in node.body:\\n            self.visit(stmt)\\n        for stmt in node.orelse:\\n            self.visit(stmt)\\n        self._loop_depth -= 1\\n\\n    def visit_ExceptHandler(self, node: ast.ExceptHandler) -> None:\\n        if node.type is None:\\n            self.findings.append(\\n                QualityFinding(\\n                    file=self.filename,\\n                    line=getattr(node, \\\"lineno\\\", 1),\\n                    severity=\\\"high\\\",\\n                    rule_id=\\\"AST-REL-BARE-EXCEPT\\\",\\n                    message=\\\"Bare `except:` block catches SystemExit/KeyboardInterrupt and hides bugs.\\\",\\n                    penalty=20.0,\\n                )\\n            )\\n        elif (\\n            len(node.body) == 1\\n            and isinstance(node.body[0], ast.Pass)\\n            and isinstance(node.type, ast.Name)\\n            and node.type.id == \\\"Exception\\\"\\n        ):\\n            self.findings.append(\\n                QualityFinding(\\n                    file=self.filename,\\n                    line=getattr(node, \\\"lineno\\\", 1),\\n                    severity=\\\"medium\\\",\\n                    rule_id=\\\"AST-REL-SWALLOWED-EXCEPTION\\\",\\n                    message=\\\"Silent `except Exception: pass` swallows runtime errors.\\\",\\n                    penalty=10.0,\\n                )\\n            )\\n        self.generic_visit(node)\\n\\n    def visit_Call(self, node: ast.Call) -> None:\\n        func_name = \\\"\\\"\\n        if isinstance(node.func, ast.Name):\\n            func_name = node.func.id\\n        elif isinstance(node.func, ast.Attribute):\\n            if isinstance(node.func.value, ast.Name):\\n                func_name = f\\\"{node.func.value.id}.{node.func.attr}\\\"\\n            else:\\n                func_name = f\\\".{node.func.attr}\\\"\\n\\n        if self._loop_depth >= 1 and func_name in (\\\"re.compile\\\", \\\".read_text\\\", \\\".write_text\\\"):\\n            self.findings.append(\\n                QualityFinding(\\n                    file=self.filename,\\n                    line=getattr(node, \\\"lineno\\\", 1),\\n                    severity=\\\"high\\\",\\n                    rule_id=\\\"AST-PERF-LOOP-INVARIANT-CALL\\\",\\n                    message=f\\\"Expensive call `{func_name}()` inside a loop; hoist outside loop or batch I/O.\\\",\\n                    penalty=18.0,\\n                )\\n            )\\n\\n        if func_name.endswith((\\\".read_text\\\", \\\".write_text\\\")):\\n            kw_names = {kw.arg for kw in node.keywords if kw.arg}\\n            if \\\"encoding\\\" not in kw_names and not node.args:\\n                self.findings.append(\\n                    QualityFinding(\\n                        file=self.filename,\\n                        line=getattr(node, \\\"lineno\\\", 1),\\n                        severity=\\\"high\\\",\\n                        rule_id=\\\"AST-IO-MISSING-UTF8-ENCODING\\\",\\n                        message=f\\\"`{func_name}()` called without explicit `encoding='utf-8'` (causes Windows cp936/gbk crashes).\\\",\\n                        penalty=15.0,\\n                    )\\n                )\\n\\n        self.generic_visit(node)\\n\\n\\ndef audit_python_path(target_path: Path, min_score: float = 90.0) -> QualityReport:\\n    \\\"\\\"\\\"Audit a Python file or directory of Python files and compute a 0..100 deterministic quality score.\\\"\\\"\\\"\\n    target_path = Path(target_path).resolve()\\n    if target_path.is_file():\\n        py_files = [target_path]\\n    else:\\n        py_files = [\\n            p\\n            for p in sorted(target_path.rglob(\\\"*.py\\\"))\\n            if \\\".evlop\\\" not in p.parts and \\\"__pycache__\\\" not in p.parts and \\\".venv\\\" not in p.parts\\n        ]\\n\\n    all_findings: list[QualityFinding] = []\\n    for py_file in py_files:\\n        try:\\n            src = py_file.read_text(encoding=\\\"utf-8\\\")\\n            tree = ast.parse(src, filename=str(py_file))\\n            visitor = _AstQualityVisitor(py_file.name)\\n            visitor.visit(tree)\\n            all_findings.extend(visitor.findings)\\n        except SyntaxError as exc:\\n            all_findings.append(\\n                QualityFinding(\\n                    file=py_file.name,\\n                    line=exc.lineno or 1,\\n                    severity=\\\"high\\\",\\n                    rule_id=\\\"AST-SYNTAX-ERROR\\\",\\n                    message=f\\\"SyntaxError: {exc.msg}\\\",\\n                    penalty=50.0,\\n                )\\n            )\\n\\n    total_penalty = sum(f.penalty for f in all_findings)\\n    score = round(max(0.0, 100.0 - total_penalty), 2)\\n    return QualityReport(\\n        target_path=str(target_path),\\n        files_scanned=len(py_files),\\n        score=score,\\n        passed=(score >= min_score),\\n        min_score=min_score,\\n        findings=all_findings,\\n    )\\n\",\n  \"sdk.py\": \"\\\"\\\"\\\"High-level programmatic Python SDK (`from evlop import EvlopEngine`) for LangGraph, CrewAI, AutoGen, and custom agents.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport hashlib\\nfrom pathlib import Path\\nfrom typing import Any, Sequence\\n\\nfrom evlop.bootstrap import bootstrap_workspace\\nfrom evlop.compiler import export_gene_to_skill, inject_markdown_file, render_lineage_mermaid\\nfrom evlop.dag_rail import DagRunRecord, execute_dag_rail\\nfrom evlop.fitness import govern_genes\\nfrom evlop.models import Episode, Gene, VerifyRecord, slugify_gene_id, utc_now_iso\\nfrom evlop.store import EvlopStore\\nfrom evlop.verifier import extract_failure_diagnosis, run_verification\\n\\n\\nclass EvlopEngine:\\n    \\\"\\\"\\\"Programmatic SDK facade for mounting EVLOP inside any Python agent runtime.\\\"\\\"\\\"\\n\\n    def __init__(self, workspace: Path | str = \\\".\\\") -> None:\\n        self.workspace = Path(workspace).resolve()\\n        self.store = EvlopStore(self.workspace)\\n        self.store.init_store()\\n\\n    def bootstrap(self, with_hooks: bool = False) -> list[Path]:\\n        cfg = self.store.load_config()\\n        return bootstrap_workspace(\\n            self.workspace,\\n            self.store.load_genes(),\\n            max_genes=cfg.max_active_genes,\\n            with_hooks=with_hooks,\\n        )\\n\\n    def recall(self, query: str = \\\"*\\\", top_k: int = 5) -> list[Gene]:\\n        return self.store.recall_genes(query, top_k=top_k)\\n\\n    def verify(self, command: str, timeout_sec: int = 120) -> VerifyRecord:\\n        record = run_verification(command, cwd=self.workspace, timeout_sec=timeout_sec)\\n        with self.store.lock():\\n            self.store.save_verify(record)\\n            if not record.passed:\\n                diag = extract_failure_diagnosis(record)\\n                self.store.save_failure(diag)\\n        return record\\n\\n    def log_experience(\\n        self,\\n        *,\\n        title: str,\\n        task: str,\\n        root_cause: str,\\n        fix: str,\\n        symptom: str = \\\"\\\",\\n        category: str = \\\"debugging\\\",\\n        trigger: str = \\\"\\\",\\n        strategy: str = \\\"\\\",\\n        anti_pattern: str = \\\"Blindly guessing without verification\\\",\\n        agent_id: str = \\\"sdk-agent\\\",\\n        from_last_failure: bool = False,\\n        failed: bool = False,\\n    ) -> Gene:\\n        with self.store.lock():\\n            cfg = self.store.load_config()\\n            last_v = self.store.load_last_verify()\\n            is_verified = bool(\\n                self.store.is_verify_fresh(last_v, ttl_minutes=cfg.verify_ttl_minutes)\\n                and not failed\\n            )\\n            verify_cmd = last_v.command if last_v else \\\"\\\"\\n\\n            eff_symptom = symptom.strip()\\n            eff_trigger = trigger.strip()\\n            if from_last_failure:\\n                last_fail = self.store.load_last_failure()\\n                if last_fail:\\n                    if not eff_symptom:\\n                        eff_symptom = f\\\"{last_fail.error_type}: {last_fail.symptom_summary}\\\"\\n                    if not eff_trigger:\\n                        eff_trigger = f\\\"{last_fail.error_type} {last_fail.symptom_summary}\\\"\\n            if not eff_symptom:\\n                eff_symptom = task.strip()\\n\\n            clean_title = title.strip() or fix.strip()[:60]\\n            gene_id = slugify_gene_id(clean_title)\\n            now_iso = utc_now_iso()\\n            ep_hash = hashlib.sha1(f\\\"{now_iso}:{task}:{gene_id}:{agent_id}\\\".encode(\\\"utf-8\\\")).hexdigest()[:10]\\n\\n            ep = Episode(\\n                episode_id=f\\\"ep-{ep_hash}\\\",\\n                timestamp=now_iso,\\n                task_summary=task,\\n                failure_symptom=eff_symptom,\\n                root_cause=root_cause,\\n                fix_applied=fix,\\n                verified=is_verified,\\n                verify_cmd=verify_cmd,\\n                gene_id=gene_id,\\n                agent_id=agent_id,\\n            )\\n            self.store.append_episode(ep)\\n\\n            genes = self.store.load_genes()\\n            new_gene = Gene(\\n                id=gene_id,\\n                title=clean_title,\\n                category=category,\\n                trigger=eff_trigger or eff_symptom,\\n                strategy=strategy.strip() or fix.strip(),\\n                anti_pattern=anti_pattern.strip(),\\n                success_count=1 if is_verified else 0,\\n                failure_count=1 if failed else 0,\\n                verified_gate=is_verified,\\n                created_at=now_iso,\\n                last_used_at=now_iso,\\n                contributors=[agent_id],\\n                best_duration_ms=last_v.duration_ms if (is_verified and last_v) else 0.0,\\n            )\\n            genes.append(new_gene)\\n            governed = govern_genes(genes, cfg)\\n            self.store.save_genes(governed)\\n            by_id = {g.id: g for g in governed}\\n            return by_id.get(gene_id, governed[0])\\n\\n    def evolve(self, targets: Sequence[str] = (\\\"AGENTS.md\\\", \\\"CLAUDE.md\\\")) -> list[Gene]:\\n        with self.store.lock():\\n            cfg = self.store.load_config()\\n            governed = govern_genes(self.store.load_genes(), cfg)\\n            self.store.save_genes(governed)\\n            for rel in targets:\\n                inject_markdown_file(self.workspace / rel, governed, max_genes=cfg.max_active_genes)\\n            return governed\\n\\n    def export_skill(self, gene_id: str, out_dir: str = \\\"skills\\\", synthesize_script: bool = True) -> Path:\\n        genes = {g.id: g for g in self.store.load_genes()}\\n        if gene_id not in genes:\\n            raise KeyError(f\\\"Gene '{gene_id}' not found.\\\")\\n        target_gene = genes[gene_id]\\n        if not target_gene.verified_gate or target_gene.status == \\\"archived\\\":\\n            raise ValueError(f\\\"Gene '{gene_id}' is unverified or archived.\\\")\\n        return export_gene_to_skill(\\n            target_gene,\\n            self.workspace / out_dir,\\n            synthesize_script=synthesize_script,\\n        )\\n\\n    def run_dag(self, spec_path: Path | str, run_id: str = \\\"\\\") -> DagRunRecord:\\n        p = Path(spec_path)\\n        if not p.is_absolute():\\n            p = (self.workspace / p).resolve()\\n        return execute_dag_rail(p, workspace=self.workspace, store=self.store, run_id=run_id)\\n\\n    def lineage_mermaid(self) -> str:\\n        cfg = self.store.load_config()\\n        return render_lineage_mermaid(govern_genes(self.store.load_genes(), cfg))\\n\\n    def status(self) -> dict[str, Any]:\\n        cfg = self.store.load_config()\\n        genes = govern_genes(self.store.load_genes(), cfg)\\n        episodes = self.store.load_episodes()\\n        return {\\n            \\\"total_episodes\\\": len(episodes),\\n            \\\"total_genes\\\": len(genes),\\n            \\\"promoted_genes\\\": sum(1 for g in genes if g.status == \\\"promoted\\\"),\\n            \\\"superseded_genes\\\": sum(1 for g in genes if g.status == \\\"superseded\\\"),\\n            \\\"archived_genes\\\": sum(1 for g in genes if g.status == \\\"archived\\\"),\\n            \\\"max_generation\\\": max((g.generation for g in genes), default=0),\\n            \\\"swarm_contributors\\\": sorted({c for g in genes for c in g.contributors}),\\n        }\\n\",\n  \"seed_genome.py\": \"\\\"\\\"\\\"Foundational SOTA Seed Genome pre-loaded when bootstrapping external agent workspaces.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom evlop.models import Gene, utc_now_iso\\n\\n\\ndef get_default_seed_genes() -> list[Gene]:\\n    \\\"\\\"\\\"Return 4 foundational SOTA engineering genes distilled from Claude 5.2/5.5, AlphaEvolve, and SWE-agent.\\\"\\\"\\\"\\n    now = utc_now_iso()\\n    return [\\n        Gene(\\n            id=\\\"gene-seed-algorithmic-complexity\\\",\\n            title=\\\"Enforce O(N) / O(1) Algorithmic Complexity and Pre-Compiled Invariants\\\",\\n            category=\\\"architecture\\\",\\n            trigger=\\\"Implementing loops, search, reconciliation, rate limiting, or data processing\\\",\\n            strategy=\\\"Use hash/dict/set indexes or monotonic deques for O(1)/O(N) lookup; hoist re.compile() and file I/O outside loops; benchmark throughput.\\\",\\n            anti_pattern=\\\"Writing O(N^2) nested scans, calling re.compile() or Path.read_text() inside loops.\\\",\\n            success_count=3,\\n            failure_count=0,\\n            verified_gate=True,\\n            created_at=now,\\n            last_used_at=now,\\n            status=\\\"promoted\\\",\\n            fitness=2.15,\\n            contributors=[\\\"evlop-seed-genome\\\"],\\n            best_duration_ms=5.0,\\n        ),\\n        Gene(\\n            id=\\\"gene-seed-numerical-and-boundary-safety\\\",\\n            title=\\\"Enforce Exact Numerical Precision, Explicit UTF-8 I/O, and Boundary Guards\\\",\\n            category=\\\"debugging\\\",\\n            trigger=\\\"Financial/rate math, file I/O, or handling empty/None/concurrent inputs\\\",\\n            strategy=\\\"Use decimal.Decimal with ROUND_HALF_UP for exact rates/money, pass encoding='utf-8' to all file/subprocess I/O, and guard empty/boundary inputs.\\\",\\n            anti_pattern=\\\"Using binary float for exact decimals, omitting encoding='utf-8', or writing bare except: pass blocks.\\\",\\n            success_count=3,\\n            failure_count=0,\\n            verified_gate=True,\\n            created_at=now,\\n            last_used_at=now,\\n            status=\\\"promoted\\\",\\n            fitness=2.10,\\n            contributors=[\\\"evlop-seed-genome\\\"],\\n            best_duration_ms=8.0,\\n        ),\\n        Gene(\\n            id=\\\"gene-seed-deterministic-verification-and-ast-audit\\\",\\n            title=\\\"Enforce Deterministic Test Verification and AST Quality Gate Before Completion\\\",\\n            category=\\\"testing\\\",\\n            trigger=\\\"Completing any feature, bugfix, or refactoring task\\\",\\n            strategy=\\\"Write adversarial unit tests (boundary, concurrency, scale), run `evlop verify --quality-gate <path>`, and require 0 test failures and AST quality score >= 90.\\\",\\n            anti_pattern=\\\"Claiming completion based on reading diffs without running `evlop verify` and `evlop audit`.\\\",\\n            success_count=3,\\n            failure_count=0,\\n            verified_gate=True,\\n            created_at=now,\\n            last_used_at=now,\\n            status=\\\"promoted\\\",\\n            fitness=2.05,\\n            contributors=[\\\"evlop-seed-genome\\\"],\\n            best_duration_ms=10.0,\\n        ),\\n        Gene(\\n            id=\\\"gene-seed-subagent-isolation-and-dag-waves\\\",\\n            title=\\\"Enforce Subagent Context Isolation and Topological DAG Wave Concurrency\\\",\\n            category=\\\"workflow\\\",\\n            trigger=\\\"Exploring >5 unfamiliar files or orchestrating multi-module agent workflows\\\",\\n            strategy=\\\"Isolate broad file exploration inside read-only subagents and execute independent multi-agent tasks in topological parallel waves via `evlop dag run`.\\\",\\n            anti_pattern=\\\"Dumping raw multi-file search outputs into the primary context window or running independent agents sequentially.\\\",\\n            success_count=3,\\n            failure_count=0,\\n            verified_gate=True,\\n            created_at=now,\\n            last_used_at=now,\\n            status=\\\"promoted\\\",\\n            fitness=2.00,\\n            contributors=[\\\"evlop-seed-genome\\\"],\\n            best_duration_ms=12.0,\\n        ),\\n    ]\\n\",\n  \"store.py\": \"\\\"\\\"\\\"Workspace persistence store (.evlop/) with cross-process locking, TTL check, and Mtime-Cached Inverted Index.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextlib import contextmanager\\nfrom dataclasses import dataclass\\nfrom datetime import datetime, timezone\\nimport json\\nimport math\\nimport os\\nfrom pathlib import Path\\nimport threading\\nimport time\\nfrom typing import Iterator\\nimport uuid\\n\\nfrom evlop.fitness import tokenize\\nfrom evlop.models import Episode, EvlopConfig, FailureDiagnosis, Gene, VerifyRecord\\n\\n_IN_PROCESS_LOCK = threading.RLock()\\n\\n\\n@dataclass\\nclass _CompiledSearchIndex:\\n    active_genes: list[Gene]\\n    sorted_by_fitness: list[Gene]\\n    postings: dict[str, list[tuple[int, float]]]\\n    concat_lower: list[str]\\n\\n\\n_SEARCH_INDEX_CACHE: dict[Path, tuple[int, int, float, _CompiledSearchIndex]] = {}\\n\\n\\ndef _build_compiled_index(genes: list[Gene]) -> _CompiledSearchIndex:\\n    active = [g for g in genes if g.status not in (\\\"archived\\\", \\\"superseded\\\")]\\n    sorted_by_fitness = sorted(active, key=lambda g: g.fitness, reverse=True)\\n    n_docs = len(active)\\n    if not active:\\n        return _CompiledSearchIndex([], [], {}, [])\\n\\n    doc_token_weights: list[dict[str, float]] = []\\n    df_counts: dict[str, int] = {}\\n    concat_lower: list[str] = []\\n\\n    for g in active:\\n        high_tokens = tokenize(f\\\"{g.id} {g.title} {g.trigger}\\\")\\n        med_tokens = tokenize(f\\\"{g.category} {g.strategy}\\\")\\n        anti_tokens = tokenize(g.anti_pattern)\\n        all_tokens = high_tokens | med_tokens | anti_tokens\\n\\n        weights: dict[str, float] = {}\\n        for t in all_tokens:\\n            w = 0.0\\n            if t in high_tokens:\\n                w += 3.0\\n            if t in med_tokens:\\n                w += 1.5\\n            if t not in high_tokens and t not in med_tokens and t in anti_tokens:\\n                w += 1.0\\n            weights[t] = w\\n            df_counts[t] = df_counts.get(t, 0) + 1\\n\\n        doc_token_weights.append(weights)\\n        concat_lower.append(f\\\"{g.title} {g.trigger} {g.strategy}\\\".lower())\\n\\n    postings: dict[str, list[tuple[int, float]]] = {}\\n    for doc_idx, weights in enumerate(doc_token_weights):\\n        for t, field_w in weights.items():\\n            df = df_counts[t]\\n            idf = math.log(1.0 + (max(0.0, n_docs - df) + 0.5) / (df + 0.5))\\n            postings.setdefault(t, []).append((doc_idx, idf * field_w))\\n\\n    return _CompiledSearchIndex(\\n        active_genes=active,\\n        sorted_by_fitness=sorted_by_fitness,\\n        postings=postings,\\n        concat_lower=concat_lower,\\n    )\\n\\n\\ndef _atomic_write_text(target: Path, content: str) -> None:\\n    \\\"\\\"\\\"Write text atomically via a sibling temporary file and os.replace with Windows retry.\\\"\\\"\\\"\\n    target.parent.mkdir(parents=True, exist_ok=True)\\n    tmp_path = target.parent / f\\\".{target.name}.{uuid.uuid4().hex[:8]}.tmp\\\"\\n    try:\\n        tmp_path.write_text(content, encoding=\\\"utf-8\\\")\\n        for attempt in range(15):\\n            try:\\n                os.replace(str(tmp_path), str(target))\\n                break\\n            except PermissionError:\\n                if attempt == 14:\\n                    raise\\n                time.sleep(0.01 * (attempt + 1))\\n    finally:\\n        if tmp_path.exists():\\n            try:\\n                tmp_path.unlink()\\n            except OSError:\\n                pass\\n\\n\\nclass EvlopStore:\\n    \\\"\\\"\\\"Manages .evlop/ directory state inside a project workspace with swarm concurrency safety.\\\"\\\"\\\"\\n\\n    def __init__(self, root_dir: Path) -> None:\\n        self.root_dir = Path(root_dir).resolve()\\n        self.evlop_dir = self.root_dir / \\\".evlop\\\"\\n        self.config_file = self.evlop_dir / \\\"config.json\\\"\\n        self.verify_file = self.evlop_dir / \\\"last_verify.json\\\"\\n        self.failure_file = self.evlop_dir / \\\"last_failure.json\\\"\\n        self.episodes_file = self.evlop_dir / \\\"episodes.jsonl\\\"\\n        self.genes_file = self.evlop_dir / \\\"genes.json\\\"\\n        self.lock_file = self.evlop_dir / \\\".lock\\\"\\n\\n    @contextmanager\\n    def lock(self, timeout_sec: float = 10.0) -> Iterator[None]:\\n        \\\"\\\"\\\"Acquire both in-process RLock and cross-process exclusive file lock (.evlop/.lock).\\\"\\\"\\\"\\n        self.evlop_dir.mkdir(parents=True, exist_ok=True)\\n        with _IN_PROCESS_LOCK:\\n            deadline = time.monotonic() + timeout_sec\\n            fd: int | None = None\\n            while True:\\n                try:\\n                    fd = os.open(str(self.lock_file), os.O_CREAT | os.O_EXCL | os.O_RDWR)\\n                    break\\n                except FileExistsError:\\n                    try:\\n                        if time.time() - self.lock_file.stat().st_mtime > 30.0:\\n                            self.lock_file.unlink()\\n                            continue\\n                    except OSError:\\n                        pass\\n                    if time.monotonic() >= deadline:\\n                        break\\n                    time.sleep(0.01)\\n            try:\\n                yield\\n            finally:\\n                if fd is not None:\\n                    try:\\n                        os.close(fd)\\n                    except OSError:\\n                        pass\\n                    try:\\n                        self.lock_file.unlink()\\n                    except OSError:\\n                        pass\\n\\n    def init_store(self) -> Path:\\n        \\\"\\\"\\\"Create .evlop/ directory and default files if they do not exist.\\\"\\\"\\\"\\n        with self.lock():\\n            self.evlop_dir.mkdir(parents=True, exist_ok=True)\\n            if not self.config_file.exists():\\n                self.save_config(EvlopConfig())\\n            if not self.genes_file.exists():\\n                self.save_genes([])\\n            if not self.episodes_file.exists():\\n                self.episodes_file.write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n        return self.evlop_dir\\n\\n    def load_config(self) -> EvlopConfig:\\n        if not self.config_file.exists():\\n            return EvlopConfig()\\n        data = json.loads(self.config_file.read_text(encoding=\\\"utf-8\\\"))\\n        return EvlopConfig.from_dict(data)\\n\\n    def save_config(self, config: EvlopConfig) -> None:\\n        _atomic_write_text(\\n            self.config_file,\\n            json.dumps(config.to_dict(), indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n        )\\n\\n    def save_verify(self, record: VerifyRecord) -> None:\\n        _atomic_write_text(\\n            self.verify_file,\\n            json.dumps(record.to_dict(), indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n        )\\n\\n    def load_last_verify(self) -> VerifyRecord | None:\\n        if not self.verify_file.exists():\\n            return None\\n        data = json.loads(self.verify_file.read_text(encoding=\\\"utf-8\\\"))\\n        return VerifyRecord.from_dict(data)\\n\\n    def is_verify_fresh(self, record: VerifyRecord | None, ttl_minutes: float = 30.0) -> bool:\\n        \\\"\\\"\\\"Return True only if `record` passed and was recorded within `ttl_minutes`.\\\"\\\"\\\"\\n        if not record or not record.passed or not record.timestamp:\\n            return False\\n        try:\\n            ts_str = record.timestamp[:-1] + \\\"+00:00\\\" if record.timestamp.endswith(\\\"Z\\\") else record.timestamp\\n            parsed = datetime.fromisoformat(ts_str)\\n            if parsed.tzinfo is None:\\n                parsed = parsed.replace(tzinfo=timezone.utc)\\n            elapsed_min = (datetime.now(timezone.utc) - parsed).total_seconds() / 60.0\\n            return elapsed_min <= ttl_minutes\\n        except (ValueError, TypeError):\\n            return False\\n\\n    def save_failure(self, diag: FailureDiagnosis) -> None:\\n        _atomic_write_text(\\n            self.failure_file,\\n            json.dumps(diag.to_dict(), indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n        )\\n\\n    def load_last_failure(self) -> FailureDiagnosis | None:\\n        if not self.failure_file.exists():\\n            return None\\n        data = json.loads(self.failure_file.read_text(encoding=\\\"utf-8\\\"))\\n        return FailureDiagnosis.from_dict(data)\\n\\n    def append_episode(self, ep: Episode) -> None:\\n        self.evlop_dir.mkdir(parents=True, exist_ok=True)\\n        line = json.dumps(ep.to_dict(), ensure_ascii=False)\\n        with self.episodes_file.open(\\\"a\\\", encoding=\\\"utf-8\\\") as fh:\\n            fh.write(line + \\\"\\\\n\\\")\\n\\n    def load_episodes(self) -> list[Episode]:\\n        if not self.episodes_file.exists():\\n            return []\\n        episodes: list[Episode] = []\\n        for line in self.episodes_file.read_text(encoding=\\\"utf-8\\\").splitlines():\\n            stripped = line.strip()\\n            if stripped:\\n                episodes.append(Episode.from_dict(json.loads(stripped)))\\n        return episodes\\n\\n    def load_genes(self) -> list[Gene]:\\n        if not self.genes_file.exists():\\n            return []\\n        raw = json.loads(self.genes_file.read_text(encoding=\\\"utf-8\\\"))\\n        return [Gene.from_dict(item) for item in raw]\\n\\n    def save_genes(self, genes: list[Gene]) -> None:\\n        payload = [g.to_dict() for g in genes]\\n        _atomic_write_text(\\n            self.genes_file,\\n            json.dumps(payload, indent=2, ensure_ascii=False) + \\\"\\\\n\\\",\\n        )\\n        try:\\n            st = self.genes_file.stat()\\n            _SEARCH_INDEX_CACHE[self.genes_file] = (\\n                st.st_mtime_ns,\\n                st.st_size,\\n                time.monotonic(),\\n                _build_compiled_index(genes),\\n            )\\n        except OSError:\\n            pass\\n\\n    def _get_search_index(self) -> _CompiledSearchIndex:\\n        now_mono = time.monotonic()\\n        cached = _SEARCH_INDEX_CACHE.get(self.genes_file)\\n        if cached and (now_mono - cached[2]) < 0.05:\\n            return cached[3]\\n        try:\\n            st = self.genes_file.stat()\\n            if cached and cached[0] == st.st_mtime_ns and cached[1] == st.st_size:\\n                _SEARCH_INDEX_CACHE[self.genes_file] = (cached[0], cached[1], now_mono, cached[3])\\n                return cached[3]\\n            genes = self.load_genes()\\n            compiled = _build_compiled_index(genes)\\n            _SEARCH_INDEX_CACHE[self.genes_file] = (st.st_mtime_ns, st.st_size, now_mono, compiled)\\n            return compiled\\n        except FileNotFoundError:\\n            return _CompiledSearchIndex([], [], {}, [])\\n        except OSError:\\n            return _build_compiled_index(self.load_genes())\\n\\n    def recall_genes(self, query: str, top_k: int = 5) -> list[Gene]:\\n        \\\"\\\"\\\"Search active genes in sub-millisecond time using Mtime-Cached Weighted Inverted Index.\\\"\\\"\\\"\\n        idx = self._get_search_index()\\n        if not idx.active_genes:\\n            return []\\n\\n        q_clean = query.strip()\\n        if not q_clean or q_clean == \\\"*\\\":\\n            return idx.sorted_by_fitness[:top_k]\\n\\n        q_tokens = tokenize(q_clean)\\n        lexical_scores: dict[int, float] = {}\\n        for t in q_tokens:\\n            for doc_idx, weight in idx.postings.get(t, ()):\\n                lexical_scores[doc_idx] = lexical_scores.get(doc_idx, 0.0) + weight\\n\\n        q_lower = q_clean.lower()\\n        if not lexical_scores:\\n            for doc_idx, text_lower in enumerate(idx.concat_lower):\\n                if q_lower in text_lower:\\n                    lexical_scores[doc_idx] = 1.0\\n\\n        if not lexical_scores:\\n            return []\\n\\n        scored: list[tuple[float, Gene]] = []\\n        for doc_idx, lex in lexical_scores.items():\\n            g = idx.active_genes[doc_idx]\\n            score = (max(1.0, lex) * 2.0) + g.fitness\\n            scored.append((score, g))\\n\\n        scored.sort(key=lambda pair: pair[0], reverse=True)\\n        return [g for _, g in scored[:top_k]]\\n\",\n  \"verifier.py\": \"\\\"\\\"\\\"Deterministic execution gate and automatic failure stack-trace extractor.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\nimport re\\nimport subprocess\\nimport time\\n\\nfrom evlop.models import FailureDiagnosis, VerifyRecord, utc_now_iso\\n\\n_ERROR_TYPE_RE = re.compile(\\n    r\\\"\\\\b([A-Z][A-Za-z0-9_]*(?:Error|Exception|Warning|Failure|Fault)|FAIL|ERROR|panic)\\\\b\\\"\\n)\\n\\n\\ndef extract_failure_diagnosis(record: VerifyRecord) -> FailureDiagnosis:\\n    \\\"\\\"\\\"Extract structured error_type and concise symptom line from a failing VerifyRecord.\\\"\\\"\\\"\\n    lines = [ln.strip() for ln in record.output_snippet.splitlines() if ln.strip()]\\n    error_type = \\\"ExecutionFailure\\\"\\n    symptom_summary = f\\\"Command `{record.command}` exited with code {record.exit_code}\\\"\\n\\n    for line in reversed(lines):\\n        m = _ERROR_TYPE_RE.search(line)\\n        if m:\\n            error_type = m.group(1)\\n            symptom_summary = line[:200]\\n            break\\n    else:\\n        if lines:\\n            symptom_summary = lines[-1][:200]\\n\\n    return FailureDiagnosis(\\n        command=record.command,\\n        exit_code=record.exit_code,\\n        timestamp=record.timestamp,\\n        error_type=error_type,\\n        symptom_summary=symptom_summary,\\n        output_snippet=record.output_snippet,\\n    )\\n\\n\\ndef run_verification(command: str, cwd: Path, timeout_sec: int = 120) -> VerifyRecord:\\n    \\\"\\\"\\\"Execute a verification shell command and capture its exit code, latency (ms), and output.\\\"\\\"\\\"\\n    t0 = time.perf_counter()\\n    try:\\n        proc = subprocess.run(\\n            command,\\n            shell=True,\\n            cwd=str(cwd),\\n            capture_output=True,\\n            text=True,\\n            encoding=\\\"utf-8\\\",\\n            errors=\\\"replace\\\",\\n            timeout=timeout_sec,\\n        )\\n        duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)\\n        combined = ((proc.stdout or \\\"\\\") + \\\"\\\\n\\\" + (proc.stderr or \\\"\\\")).strip()\\n        snippet = combined[-1200:] if len(combined) > 1200 else combined\\n        return VerifyRecord(\\n            command=command,\\n            exit_code=proc.returncode,\\n            passed=(proc.returncode == 0),\\n            timestamp=utc_now_iso(),\\n            output_snippet=snippet,\\n            duration_ms=duration_ms,\\n        )\\n    except subprocess.TimeoutExpired as exc:\\n        duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)\\n        return VerifyRecord(\\n            command=command,\\n            exit_code=124,\\n            passed=False,\\n            timestamp=utc_now_iso(),\\n            output_snippet=f\\\"TimeoutExpired after {timeout_sec}s: {exc}\\\",\\n            duration_ms=duration_ms,\\n        )\\n    except Exception as exc:  # pragma: no cover - defensive fallback\\n        duration_ms = round((time.perf_counter() - t0) * 1000.0, 2)\\n        return VerifyRecord(\\n            command=command,\\n            exit_code=1,\\n            passed=False,\\n            timestamp=utc_now_iso(),\\n            output_snippet=f\\\"Execution error: {exc}\\\",\\n            duration_ms=duration_ms,\\n        )\\n\"\n}")


def _ensure_embedded_package() -> Path:
    cwd_vendor = Path.cwd().resolve() / ".evlop" / "vendor"
    target_root = cwd_vendor if (Path.cwd().resolve() / ".evlop").exists() else Path(tempfile.gettempdir()) / "evlop_standalone_runtime"
    pkg_dir = target_root / "evlop"
    pkg_dir.mkdir(parents=True, exist_ok=True)
    for filename, content in _EMBEDDED_MODULES.items():
        dest = pkg_dir / filename
        if not dest.exists() or dest.read_text(encoding="utf-8") != content:
            dest.write_text(content, encoding="utf-8")
    return target_root


def main() -> int:
    runtime_root = _ensure_embedded_package()
    if str(runtime_root) not in sys.path:
        sys.path.insert(0, str(runtime_root))
    from evlop.cli import main as cli_main

    return cli_main()


if __name__ == "__main__":
    sys.exit(main())
